INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C1','kor',1,2,'u6',1,'생각을 문장으로 나타내기 — 영화관을 바르게 이용하지 않는 친구처럼 주어진 상황을 보고 「안 돼」 같은 느낌에서 그치지 않고 무엇을 어떻게 하면 좋을지와 까닭을 문장에 담기, 사람마다 생각과 표현이 다를 수 있음을 알기',ARRAY['2국03-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C2','kor',1,2,'u6',2,'문제·해결 방법·자신의 생각으로 문장 쓰기 — 「발명보다 위대한 발견」에서 낭비되는 자원을 발견하고, 더 쓸 수 있는 종이처럼 문제를 찾아 해결 방법을 정하고 까닭을 넣어 자신의 생각을 쓰기, 발명과 발견의 뜻 가르기',ARRAY['2국03-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C3','kor',1,2,'u6',4,'시를 읽고 생각을 짧은 문장으로 나타내기 — 「반짝반짝」에서 혼자 빛나는 별과 여럿이 빛나는 별자리를 찾고 둘 다 소중함을 알며, 어떻게 빛나고 싶은지·우리 반을 위해 할 일을 짧은 문장 여러 개로 쓰기, 별·별자리·혼자·여럿이·반짝·반짝반짝의 뜻',ARRAY['2국05-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C4','kor',1,2,'u6',6,'소리와 표기가 다른 낱말 바르게 쓰고 읽기 — 낮·낫·낯처럼 [낟] 하나로 소리 나도 글자와 뜻이 다른 낱말, 못·팥·윷·꽃·맡다·숯·잎·밖처럼 받침이 대표음으로 소리 나는 낱말을 바르게 쓰기, 자음자 이름(치읓·키읔·피읖·히읗) 바르게 쓰기',ARRAY['2국04-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C5','kor',1,2,'u6',8,'뜻이 통하게 문장을 자연스럽게 띄어 읽기 — 「소방관의 부탁」을 들으며 말하는 사람이 어디에서 쉬는지 살피고, 글자마다 끊거나 쉬지 않고 빠르게 읽지 않으며 뜻이 이어지는 덩어리로 띄어 읽기, 쉬는 곳이 여럿일 수 있음을 알기',ARRAY['2국02-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C6','kor',1,2,'u6',10,'글의 의미를 생각하며 읽기 — 「괜찮아 아저씨」에서 머리카락이 빠진 까닭과 머리 모양의 변화를 글과 그림으로 찾고, 「오, 괜찮은데?」에 담긴 마음을 알며, 흉내 내는 말을 살려 자연스럽게 읽기(누가 뒤·문장 사이에서 쉬기)',ARRAY['2국02-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C7','kor',1,2,'u6',13,'목소리 연극으로 자연스럽게 읽기 — 공작새·꾀꼬리·하늘 대본에서 인물의 마음을 짐작하고 문장 부호를 살려 대사를 띄어 읽기, 친구의 읽기를 외모·말버릇이 아니라 자연스럽게 읽는지로 평가하고 진지하게 듣기',ARRAY['2국02-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C8','kor',1,2,'u6',15,'반대말 알기 — 들어가다·나가다, 싫다·좋다, 더럽다·깨끗하다, 묶다·풀다, 밝다·어둡다, 빠르다·느리다처럼 뜻이 반대인 낱말을 짝짓고 문장에 넣기, 「안」을 붙인 말은 반대말이 아님(기초 다지기)',ARRAY['2국04-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X01','kor',1,'u6',ARRAY['K1-2-u6-C1','K1-2-u6-C2','K1-2-u6-C3']::text[],'「안 돼·좋았어요」처럼 느낌이나 한마디에서 그치고 무엇을 어떻게 하면 좋을지 말하지 않는다','「그래서 어떻게 하면 좋을까?」 한 번 더 묻기 — 느낌 뒤에 「~해야 해 / ~하면 좋겠어요」를 붙이게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X02','kor',1,'u6',ARRAY['K1-2-u6-C1','K1-2-u6-C2']::text[],'「하지 마」처럼 까닭 없이 하라·하지 말라고만 해서 왜 그래야 하는지 전해지지 않는다','「왜?」를 붙여 보게 하기 — 「앞사람이 불편할 수도 있으니까 ~」처럼 「~니까」를 넣어 고쳐 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X03','kor',1,'u6',ARRAY['K1-2-u6-C1','K1-2-u6-C3']::text[],'같은 상황·같은 시를 보고 나와 생각이나 표현이 다르면 틀렸다고 한다','「사람마다 떠올리는 생각이 달라요」 — 친구 문장과 내 문장을 나란히 읽고 「왜 그렇게 썼어?」 묻게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X04','kor',1,'u6',ARRAY['K1-2-u6-C2','K1-2-u6-C1']::text[],'그림에 없는 문제를 지어내거나 바르게 하는 모습처럼 문제가 아닌 것을 문제로 고른다','그림에서 「무엇이 낭비되고 있나?」를 손가락으로 짚게 하기 — 보이는 것만 문제로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X05','kor',1,'u6',ARRAY['K1-2-u6-C2']::text[],'문제를 풀지 못하는 해결 방법을 고른다(아예 쓰지 않기·더 많이 쓰기·버리기)','「그렇게 하면 처음 문제가 정말 없어지나요?」 — 지금 내가 할 수 있는 일인지 함께 따져 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X06','kor',1,'u6',ARRAY['K1-2-u6-C2']::text[],'문제·해결 방법·자신의 생각 가운데 하나를 빠뜨리거나 칸의 차례·자리를 뒤섞는다','세 칸에 손가락을 짚으며 「무엇이 문제? → 어떻게? → 내 생각과 까닭」 차례로 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X07','kor',1,'u6',ARRAY['K1-2-u6-C1','K1-2-u6-C2','K1-2-u6-C3']::text[],'발명과 발견처럼 비슷한 낱말의 뜻을 섞거나, 길게 한 문장으로 이어 쓰는 것을 잘 쓴 것으로 여긴다','「새로 만들었나, 있던 것을 찾았나?」로 발명·발견 가르기 — 긴 한 문장과 짧은 문장 여러 개를 읽어 주고 어느 쪽이 잘 들리는지 고르게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X08','kor',1,'u6',ARRAY['K1-2-u6-C3']::text[],'시의 내용을 잘못 읽거나(별과 별자리를 뒤바꿈, 시에 없는 것) 시와 상관없는 말을 생각이라고 한다','「혼자 / 여럿이」 두 칸에 시의 물음을 나누어 적게 하고, 생각은 「나는 ~ 별(별자리)이 되고 싶어요」로 쓰게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X09','kor',1,'u6',ARRAY['K1-2-u6-C3']::text[],'혼자 하는 일과 함께 하는 일을 가리지 못하거나, 둘 가운데 하나만 소중하다고 여긴다','「혼자서도 할 수 있는 일 / 여럿이 있어야 되는 일」 두 칸 놀이 — 그리고 「둘 다 빛나요」로 마무리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X10','kor',1,'u6',ARRAY['K1-2-u6-C4']::text[],'받침의 소리와 글자가 같다고 여겨 소리 나는 대로 쓴다(꽃→꼳, 맡→맏, 숯→숟, 윷→윧)','낱말을 소리 내어 읽은 뒤 글자를 보고 「소리는 [꼳], 글자는 꽃」 두 줄로 나누어 적게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X11','kor',1,'u6',ARRAY['K1-2-u6-C4']::text[],'소리가 같으면 같은 낱말·같은 뜻이라고 여긴다(낮·낫·낯, 입·잎, 같다·갔다)','세 낱말을 그림 카드와 짝짓게 하기 — 소리는 [낟]으로 같아도 글자가 다르면 뜻이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X12','kor',1,'u6',ARRAY['K1-2-u6-C4']::text[],'자음자 이름을 소리 나는 대로 쓴다(키읔→키윽, 피읖→피읍, 히읗→히읃)','「이름 끝 받침 자리에 그 자음자가 숨어 있어요」 — ㅋ의 이름 끝 받침에도 ㅋ') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X13','kor',1,'u6',ARRAY['K1-2-u6-C5','K1-2-u6-C6','K1-2-u6-C7']::text[],'글자마다 끊어 읽거나 낱말 가운데에서 쉬어 뜻을 끊는다','낱말 카드를 하나씩 통째로 짚으며 읽기 — 낱말은 한 덩어리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X14','kor',1,'u6',ARRAY['K1-2-u6-C5','K1-2-u6-C6']::text[],'쉬지 않고 빠르게 붙여 읽어 듣는 사람이 뜻을 잡기 어렵게 한다','㉮(붙여 읽기)와 ㉯(띄어 읽기)를 들려주고 어느 쪽이 더 잘 들리는지 고르게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X15','kor',1,'u6',ARRAY['K1-2-u6-C5']::text[],'띄어 읽는 곳은 하나로 정해져 있다고 여기거나, 띄어 쓴 곳마다 모두 쉬어야 한다고 여긴다','「불이 나면∨모두의 안전을 위해…」 두 가지 읽기를 들려주고 「둘 다 뜻이 통하나?」 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X16','kor',1,'u6',ARRAY['K1-2-u6-C6']::text[],'「누가·무엇이」에 해당하는 말 뒤나 문장과 문장 사이에서 쉬어야 함을 모른다','문장마다 「누가?」 물어 답이 되는 말에 동그라미 — 동그라미 뒤에 ∨, 마침표 뒤에는 조금 더 쉬기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X17','kor',1,'u6',ARRAY['K1-2-u6-C6','K1-2-u6-C5','K1-2-u6-C7','K1-2-u6-C1','K1-2-u6-C2','K1-2-u6-C3']::text[],'글이나 이야기의 내용·까닭·차례를 글과 다르게 읽는다','「그 일이 글 어디에 있나요?」 줄과 그림을 짚게 하고, 머리카락 수처럼 바뀌는 것을 차례로 세어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X18','kor',1,'u6',ARRAY['K1-2-u6-C7']::text[],'문장 부호를 살리지 않고 읽는다(느낌표를 힘없이·물음표를 내려·마침표에서 쉬지 않기)','부호 카드(. ? !)를 들고 같은 대사를 세 가지로 읽어 보기 — 끝이 어떻게 달라지나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X19','kor',1,'u6',ARRAY['K1-2-u6-C7','K1-2-u6-C5']::text[],'친구의 읽기를 외모·말버릇·빠르기처럼 읽기와 상관없는 것으로 평가하거나, 틀리면 웃는 등 진지하게 듣지 않는다','「자연스럽게 읽었나요?」 하나만 평가지에 남기기 — 듣는 사람은 바라보며 끝까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X20','kor',1,'u6',ARRAY['K1-2-u6-C8']::text[],'반대말을 짝짓지 못하거나 「안」을 붙인 말·뜻이 비슷한 말을 반대말로 쓴다','몸으로 보여 주기 — 들어가고 나가며, 묶고 풀며 짝 낱말 말하기 — 「안 들어가다」는 반대말이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#1','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',1,'mc','auto','『국어』 179쪽 생각 열기 — 사람들이 화면에서 보고 있는 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"『국어』 179쪽 생각 열기 — 사람들이 화면에서 보고 있는 것은?","options":[{"t":"비상 대피도","correct":true},{"t":"만화 영화 예고편","mis":"K1-2-u6-X17"},{"t":"팝콘 가게 광고","mis":"K1-2-u6-X17"}],"explanation":["화면에 비상 대피도가 나와요.","불이 나면 어디로 나가야 하는지 알려 줘요.","179쪽 그림이에요."],"asset":{"type":"scene","icon":"🗺️➡️🚪","text":"『국어』 179쪽 — 영화관 화면에 비상 대피도가 나와요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#2','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',1,'mc','auto','비상 대피도의 화살표가 알려 주는 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":2,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"비상 대피도의 화살표가 알려 주는 것은?","options":[{"t":"대피하는 방향","correct":true},{"t":"표를 사는 곳","mis":"K1-2-u6-X17"},{"t":"의자 번호","mis":"K1-2-u6-X17"}],"explanation":["화살표는 대피 방향이에요.","화살표를 따라가면 비상구가 나와요.","지도서 246쪽이에요."],"asset":{"type":"scene","icon":"🗺️➡️🚪","text":"『국어』 179쪽 — 영화관 화면에 비상 대피도가 나와요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#3','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',1,'mc','auto','위험한 상황에서는 어떻게 행동해야 할까요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":3,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"위험한 상황에서는 어떻게 행동해야 할까요?","options":[{"t":"당황하지 않고 비상구 위치를 찾아요","correct":true},{"t":"자리에 앉아 영화를 계속 봐요","mis":"K1-2-u6-X17"},{"t":"친구를 밀치고 먼저 뛰어나가요","mis":"K1-2-u6-X17"}],"explanation":["미리 알아 둔 비상구로 차분하게 나가요.","밀치면 더 위험해요.","지도서 246쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#4','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',1,'mc','auto','『국어』 180쪽 1번 — 영화관을 바르게 이용하지 않는 친구는?',ARRAY['K1-2-u6-X04']::text[],false,'{"seq":4,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"『국어』 180쪽 1번 — 영화관을 바르게 이용하지 않는 친구는?","options":[{"t":"영화 장면을 휴대 전화로 찍는 친구","correct":true},{"t":"조용히 영화를 보는 친구","mis":"K1-2-u6-X04"},{"t":"자리에 바르게 앉은 친구","mis":"K1-2-u6-X04"}],"explanation":["영화 장면을 찍으면 안 돼요.","조용히 보고 바르게 앉은 친구는 잘하고 있어요.","180쪽 1번이에요."],"asset":{"type":"scene","icon":"📱🎬","text":"영화관에서 한 친구가 영화 장면을 휴대 전화로 찍어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#5','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',2,'match','auto','『국어』 180쪽 2번 — 친구가 한 일과 해 주고 싶은 말을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u6-C1","difficulty":2,"kind":"match","stem":"『국어』 180쪽 2번 — 친구가 한 일과 해 주고 싶은 말을 이어 보세요.","pairs":[{"l":"장면을 휴대 전화로 찍어요","r":"영화에 나오는 장면을 휴대 전화로 찍으면 안 돼."},{"l":"앞자리를 발로 차요","r":"앞사람이 불편할 수도 있으니까 앞자리를 발로 차면 안 돼."},{"l":"쓰레기를 두고 가요","r":"쓰레기는 영화가 끝난 뒤에 밖에 있는 쓰레기통에 버려야 해."}],"mis":"K1-2-u6-X04","explanation":["상황에 맞는 말을 찾아요.","생각을 문장으로 말하면 잘 전해져요.","180쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#6','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',2,'mc','auto','휴대 전화가 울린 친구에게 해 주고 싶은 말로 알맞은 것은?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":6,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"휴대 전화가 울린 친구에게 해 주고 싶은 말로 알맞은 것은?","options":[{"t":"영화관에서는 휴대 전화에서 소리나 진동이 울리지 않게 해야 해.","correct":true},{"t":"시끄러워.","mis":"K1-2-u6-X01"},{"t":"저리 가.","mis":"K1-2-u6-X02"}],"explanation":["무엇을 어떻게 해야 하는지 말했어요.","느낌 한마디만으로는 잘 전해지지 않아요.","181쪽 예시 답안이에요."],"asset":{"type":"scene","icon":"📳🎬","text":"영화를 보는데 한 친구의 휴대 전화가 울려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#7','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',2,'mc','auto','큰 소리로 떠드는 친구에게 해 주고 싶은 말로 알맞은 것은?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":7,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"큰 소리로 떠드는 친구에게 해 주고 싶은 말로 알맞은 것은?","options":[{"t":"영화를 볼 때에는 큰 소리로 이야기하거나 시끄럽게 하면 안 돼.","correct":true},{"t":"너희 싫어.","mis":"K1-2-u6-X01"},{"t":"나가.","mis":"K1-2-u6-X02"}],"explanation":["영화를 볼 때 지킬 일을 문장으로 말했어요.","느낌이나 명령만으로는 잘 전해지지 않아요.","181쪽 예시 답안이에요."],"asset":{"type":"scene","icon":"🗣️🎬","text":"영화관에서 두 친구가 큰 소리로 떠들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#8','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',2,'ox','auto','같은 그림을 보고도 친구마다 해 주고 싶은 말이 다를 수 있어요.',ARRAY['K1-2-u6-X03']::text[],false,'{"seq":8,"concept":"K1-2-u6-C1","difficulty":2,"kind":"ox","stem":"같은 그림을 보고도 친구마다 해 주고 싶은 말이 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 떠올리는 생각과 표현이 다르니까","correct":true},{"t":"정답 문장은 하나뿐이니까","mis":"K1-2-u6-X03"}],"mis":"K1-2-u6-X03","explanation":["사람마다 생각을 다양하게 표현해요.","친구의 생각도 존중해요.","지도서 246쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#9','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','『국어』 181쪽 3번 — 친구들이 문장을 읽는 것을 들으면 알 수 있는 것은?',ARRAY['K1-2-u6-X15','K1-2-u6-X19']::text[],false,'{"seq":9,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"『국어』 181쪽 3번 — 친구들이 문장을 읽는 것을 들으면 알 수 있는 것은?","options":[{"t":"사람마다 빠르기, 목소리 크기, 띄어 읽는 곳이 달라요","correct":true},{"t":"모든 사람이 똑같이 읽어요","mis":"K1-2-u6-X15"},{"t":"빨리 읽는 사람이 잘 읽은 거예요","mis":"K1-2-u6-X19"}],"explanation":["사람마다 읽는 방식이 달라요.","다른 사람의 읽기와 견주며 자연스러운 읽기를 찾아요.","지도서 247쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#10','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',3,'mc','auto','앞자리를 차는 친구에게 해 줄 말로 생각이 가장 잘 드러난 것은?',ARRAY['K1-2-u6-X02','K1-2-u6-X01']::text[],false,'{"seq":10,"concept":"K1-2-u6-C1","difficulty":3,"kind":"mc","stem":"앞자리를 차는 친구에게 해 줄 말로 생각이 가장 잘 드러난 것은?","options":[{"t":"앞사람이 불편할 수도 있으니까 앞자리를 발로 차면 안 돼.","correct":true},{"t":"앞자리를 발로 차면 안 돼.","mis":"K1-2-u6-X02"},{"t":"앞사람이 화났어.","mis":"K1-2-u6-X01"}],"explanation":["까닭과 할 일이 함께 있어요.","까닭이 빠지거나 느낌만 있으면 덜 전해져요.","180쪽 예시 답안이에요."],"asset":{"type":"scene","icon":"🦶💺","text":"영화관에서 한 친구가 앞자리를 발로 차요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
