INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#3','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'error','auto','쓰레기를 두고 가는 친구에게 「더러워.」라고만 말했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":3,"concept":"K1-2-u6-C1","difficulty":3,"kind":"error","stem":"쓰레기를 두고 가는 친구에게 「더러워.」라고만 말했어요. 무엇이 아쉬운가요?","options":[{"t":"느낌만 말했어요 — 쓰레기를 어떻게 해야 하는지 말해요","correct":true,"mis_target":"K1-2-u6-X01"},{"t":"잘 말했어요","mis":"K1-2-u6-X01"},{"t":"「싫어.」라고 바꾸면 돼요","mis":"K1-2-u6-X01"}],"explanation":["느낌에서 한 걸음 더 나아가요.","「쓰레기는 밖에 있는 쓰레기통에 버려야 해.」처럼요.","지도서 247쪽이에요."],"asset":{"type":"scene","icon":"🍿🗑️","text":"영화관에서 한 친구가 다 먹은 팝콘 통을 바닥에 두고 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#4','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'error','auto','앞자리를 차는 친구에게 「하지 마.」라고만 말했어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u6-X02','K1-2-u6-X07']::text[],false,'{"seq":4,"concept":"K1-2-u6-C1","difficulty":3,"kind":"error","stem":"앞자리를 차는 친구에게 「하지 마.」라고만 말했어요. 무엇이 아쉬운가요?","options":[{"t":"왜 하면 안 되는지 까닭이 없어요","correct":true,"mis_target":"K1-2-u6-X02"},{"t":"잘 말했어요","mis":"K1-2-u6-X02"},{"t":"말이 너무 길어요","mis":"K1-2-u6-X07"}],"explanation":["「앞사람이 불편할 수도 있으니까」처럼 까닭을 넣어요.","짧아서 뜻이 덜 전해져요.","180쪽 예시 답안이에요."],"asset":{"type":"scene","icon":"🦶💺","text":"영화관에서 한 친구가 앞자리를 발로 차요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#5','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'mc','auto','『국어활동』 62쪽 — 차 안 그림을 보고 생각이 잘 드러나게 표현한 것은?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":5,"concept":"K1-2-u6-C1","difficulty":3,"kind":"mc","stem":"『국어활동』 62쪽 — 차 안 그림을 보고 생각이 잘 드러나게 표현한 것은?","options":[{"t":"안전을 위해 차에서는 안전띠를 풀지 않아야 해요.","correct":true},{"t":"하면 안 돼요.","mis":"K1-2-u6-X01"},{"t":"차가 좋아요.","mis":"K1-2-u6-X01"}],"explanation":["무엇을 왜 해야 하는지 드러나요.","「하면 안 돼요.」는 무엇을 하면 안 되는지 몰라요.","국어활동 62쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#6','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'mc','auto','『국어활동』 62쪽 — 책상 위를 보고 생각이 잘 드러나게 표현한 것은?',ARRAY['K1-2-u6-X01','K1-2-u6-X04']::text[],false,'{"seq":6,"concept":"K1-2-u6-C1","difficulty":3,"kind":"mc","stem":"『국어활동』 62쪽 — 책상 위를 보고 생각이 잘 드러나게 표현한 것은?","options":[{"t":"주변이 너무 지저분하니까 정리를 해야 해요.","correct":true},{"t":"내 책상 위가 이상해요.","mis":"K1-2-u6-X01"},{"t":"책상이 커요.","mis":"K1-2-u6-X04"}],"explanation":["까닭과 할 일이 함께 있어요.","「이상해요」는 느낌만 있어요.","국어활동 62쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#7','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'mc','auto','『국어활동』 62쪽 — 책을 읽고 생각이 잘 드러나게 표현한 것은?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":7,"concept":"K1-2-u6-C1","difficulty":3,"kind":"mc","stem":"『국어활동』 62쪽 — 책을 읽고 생각이 잘 드러나게 표현한 것은?","options":[{"t":"이 책은 주인공이 모험을 하는 내용이 있어서 재미있어요.","correct":true},{"t":"이 책은 좋아요.","mis":"K1-2-u6-X01"},{"t":"책이에요.","mis":"K1-2-u6-X01"}],"explanation":["왜 재미있는지 까닭이 있어요.","「좋아요」만으로는 생각이 드러나지 않아요.","국어활동 62쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#8','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',4,'sa','auto','「앞사람이 불편할 수도 있으◯◯ 앞자리를 발로 차면 안 돼.」 — 까닭을 이어 주는 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u6-C1","difficulty":4,"kind":"sa","stem":"「앞사람이 불편할 수도 있으◯◯ 앞자리를 발로 차면 안 돼.」 — 까닭을 이어 주는 빈칸 두 글자를 쓰세요.","answer":["니까"],"explanation":["「~니까」로 까닭을 이어요.","앞사람이 불편할 수도 있으니까.","180쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#9','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',4,'essay','teacher','『국어활동』 63쪽 — 급식 시간에 「싫어요.」라고만 말한 친구가 있어요. 이 음식을 먹으면 피부가 빨개지고 가려워진대요. 말하고 싶은 내용이 잘 드러나게 바꾸어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"『국어활동』 63쪽 — 급식 시간에 「싫어요.」라고만 말한 친구가 있어요. 이 음식을 먹으면 피부가 빨개지고 가려워진대요. 말하고 싶은 내용이 잘 드러나게 바꾸어 쓰세요.","answer_guide":{"answer":"예: 저는 이 음식을 먹으면 피부가 빨개지고 가려워져서 먹고 싶지 않아요. — 무엇이 싫은지와 까닭이 있으면 맞아요.","scoring_points":["무엇을 말하려는지 드러나는가","까닭을 넣었는가","완결된 문장으로 썼는가"]},"explanation":["「싫어요」만으로는 선생님이 까닭을 몰라요.","까닭을 넣어 바꾸어 써요.","국어활동 63쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#10','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',4,'essay','teacher','영화관을 바르게 이용하는 친구에게 해 주고 싶은 말을 까닭과 함께 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"영화관을 바르게 이용하는 친구에게 해 주고 싶은 말을 까닭과 함께 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 조용히 영화를 봐 줘서 고마워, 덕분에 영화를 재미있게 봤어. — 친구가 한 일과 내 생각이 드러나면 맞아요.","scoring_points":["친구가 한 일을 말했는가","내 생각이나 까닭이 있는가","완결된 문장인가"]},"explanation":["바르게 이용하는 모습을 떠올려요.","느낌에서 한 걸음 더 나아가요.","지도서 247쪽 추가 발문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
