INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#6','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',3,'mc','auto','『국어』 185쪽 6번 — 복도에서 뛰는 친구를 보고 쓴 자신의 생각으로 알맞은 것은?',ARRAY['K1-2-u6-X02','K1-2-u6-X04']::text[],false,'{"seq":6,"concept":"K1-2-u6-C2","difficulty":3,"kind":"mc","stem":"『국어』 185쪽 6번 — 복도에서 뛰는 친구를 보고 쓴 자신의 생각으로 알맞은 것은?","options":[{"t":"친구와 부딪혀 다칠 수 있으니까 걸어 다니면 좋겠어요.","correct":true},{"t":"뛰지 마.","mis":"K1-2-u6-X02"},{"t":"복도가 길어요.","mis":"K1-2-u6-X04"}],"explanation":["까닭과 할 일이 함께 있어요.","까닭 없는 말, 문제와 상관없는 말은 아쉬워요.","지도서 249쪽이에요."],"asset":{"type":"scene","icon":"🏃🏫","text":"지도서 249쪽 — 복도에서 친구가 뛰어다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#7','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',3,'match','auto','친구 물건을 말없이 쓰는 상황 — 칸과 쓸 내용을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u6-C2","difficulty":3,"kind":"match","stem":"친구 물건을 말없이 쓰는 상황 — 칸과 쓸 내용을 이어 보세요.","pairs":[{"l":"문제","r":"친구의 물건을 말없이 가져가 써요."},{"l":"해결 방법","r":"쓰기 전에 친구에게 먼저 물어봐요."},{"l":"자신의 생각","r":"친구가 속상하니까 먼저 물어보면 좋겠어요."}],"mis":"K1-2-u6-X06","explanation":["세 칸에 맞게 이어요.","자신의 생각에는 까닭이 있어요.","지도서 249쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#8','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',4,'sa','auto','『국어』 185쪽 보기 — 「종이의 (  )을 써요.」 빈칸에 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u6-C2","difficulty":4,"kind":"sa","stem":"『국어』 185쪽 보기 — 「종이의 (  )을 써요.」 빈칸에 알맞은 낱말을 쓰세요.","answer":["뒷면"],"explanation":["종이의 뒷면을 써요.","빈 부분을 써도 좋아요.","185쪽 보기예요."],"asset":{"type":"passage","lines":["문제: 더 쓸 수 있는 종이를 버리려고 해요.","해결 방법: 종이의 뒷면을 써요.","자신의 생각: 아직 더 쓸 수 있으니까 종이의 뒷면도 쓰면 좋겠어요."],"title":"『국어』 185쪽 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#9','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',4,'essay','teacher','지우개를 잘라서 놀이하는 그림을 보고, 문제·해결 방법·자신의 생각을 차례로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C2","difficulty":4,"kind":"essay","stem":"지우개를 잘라서 놀이하는 그림을 보고, 문제·해결 방법·자신의 생각을 차례로 쓰세요.","answer_guide":{"answer":"예: 문제 — 지우개를 잘라서 놀이를 해요. / 해결 방법 — 지우개는 글씨를 지울 때만 써요. / 자신의 생각 — 지우개가 금방 없어지니까 아껴 쓰면 좋겠어요. — 세 칸이 차례대로 있고 까닭이 있으면 맞아요.","scoring_points":["문제를 바르게 찾았는가","할 수 있는 해결 방법인가","자신의 생각에 까닭이 있는가"]},"explanation":["그림에 보이는 문제부터 써요.","까닭을 넣어 생각을 써요.","185쪽 6번이에요."],"asset":{"type":"scene","icon":"✂️🧽","text":"지도서 248쪽 — 친구들이 지우개를 잘라서 놀이를 해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#10','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',4,'essay','teacher','「발명보다 위대한 발견」처럼 우리 반에서 낭비되는 것을 하나 발견하고, 어떻게 하면 좋을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C2","difficulty":4,"kind":"essay","stem":"「발명보다 위대한 발견」처럼 우리 반에서 낭비되는 것을 하나 발견하고, 어떻게 하면 좋을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 아무도 없는 교실에 불이 켜져 있어요. 전기가 낭비되니까 나갈 때 불을 끄면 좋겠어요. — 발견한 것과 방법, 까닭이 있으면 맞아요.","scoring_points":["낭비되는 것을 찾았는가","어떻게 하면 좋을지 썼는가","까닭이 있는가"]},"explanation":["주변을 둘러보며 낭비되는 것을 찾아요.","짧은 문장 여러 개로 써도 좋아요.","지도서 248쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#1','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',1,'mc','auto','『국어』 186쪽 — 시 「반짝반짝」이 우리에게 묻는 것은?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":1,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 186쪽 — 시 「반짝반짝」이 우리에게 묻는 것은?","options":[{"t":"혼자 빛나는 별이 될지, 여럿이 빛나는 별자리가 될지","correct":true},{"t":"해가 왜 뜨는지","mis":"K1-2-u6-X08"},{"t":"달이 몇 개인지","mis":"K1-2-u6-X08"}],"explanation":["시는 별과 별자리를 물어요.","교과서 186쪽에서 시를 소리 내어 읽어요.","186쪽이에요."],"asset":{"type":"passage","lines":["시 「반짝반짝」은 우리에게 두 가지를 물어요.","하나는 혼자서 빛나는 별이 되고 싶은지,","하나는 여럿이 모여 빛나는 별자리가 되고 싶은지예요."],"title":"『국어』 186쪽 — 시가 묻는 것(풀어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#2','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',1,'mc','auto','『국어』 187쪽 (1) — 혼자 반짝 빛날 수 있는 때는?',ARRAY['K1-2-u6-X09']::text[],false,'{"seq":2,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 187쪽 (1) — 혼자 반짝 빛날 수 있는 때는?","options":[{"t":"쓰레기를 스스로 주울 때","correct":true},{"t":"친구를 놀릴 때","mis":"K1-2-u6-X09"},{"t":"숙제를 미룰 때","mis":"K1-2-u6-X09"}],"explanation":["누가 보지 않아도 스스로 하는 일이 빛나요.","놀리거나 미루는 일은 빛나지 않아요.","187쪽 (1)이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"쓰레기를 스스로 주울 때 나 혼자 반짝 빛날 수 있어."},{"who":"친구 2","text":"내 생각을 마음껏 표현할 때에도 그래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#3','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',1,'mc','auto','『국어』 187쪽 (2) — 여럿이 함께 빛날 수 있는 때는?',ARRAY['K1-2-u6-X09']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 187쪽 (2) — 여럿이 함께 빛날 수 있는 때는?","options":[{"t":"도움이 필요한 친구를 함께 도와줄 때","correct":true},{"t":"혼자만 놀이 기구를 탈 때","mis":"K1-2-u6-X09"},{"t":"친구 물건을 몰래 가져갈 때","mis":"K1-2-u6-X09"}],"explanation":["여럿이 마음을 모으면 더 빛나요.","혼자만 하거나 몰래 가져가는 일은 아니에요.","187쪽 (2)예요."],"asset":{"type":"speech","turns":[{"who":"친구 3","text":"함께 즐거움을 느낄 때 우리 모두 빛날 수 있어."},{"who":"친구 4","text":"도움이 필요한 친구를 함께 도와줄 때에도 그래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#4','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',1,'mc','auto','『국어』 188쪽 낱말 알기 — 여러 별이 모인 무리를 뜻하는 낱말은?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":4,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 188쪽 낱말 알기 — 여러 별이 모인 무리를 뜻하는 낱말은?","options":[{"t":"별자리","correct":true},{"t":"별","mis":"K1-2-u6-X08"},{"t":"별빛","mis":"K1-2-u6-X08"}],"explanation":["별이 모이면 별자리예요.","별은 하나로 빛나는 것이에요.","188쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#5','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',2,'match','auto','『국어』 188쪽 — 낱말과 뜻을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u6-C3","difficulty":2,"kind":"match","stem":"『국어』 188쪽 — 낱말과 뜻을 이어 보세요.","pairs":[{"l":"별","r":"하나로 빛나는 것"},{"l":"별자리","r":"여러 별이 모인 무리"},{"l":"여럿이","r":"많은 사람이 함께"}],"mis":"K1-2-u6-X08","explanation":["별과 혼자, 별자리와 여럿이가 닮았어요.","낱말의 관계를 생각해요.","188쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#6','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',2,'mc','auto','『국어』 188쪽 — 「반짝반짝」의 뜻으로 알맞은 것은?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":6,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"『국어』 188쪽 — 「반짝반짝」의 뜻으로 알맞은 것은?","options":[{"t":"작은 빛이 여러 번 계속 빛나는 모양","correct":true},{"t":"한 번만 빛나는 모양","mis":"K1-2-u6-X08"},{"t":"빛이 꺼지는 모양","mis":"K1-2-u6-X08"}],"explanation":["「반짝반짝」은 여러 번 계속이에요.","한 번은 「반짝」이에요.","지도서 251쪽 — 몸으로 표현해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#7','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',2,'mc','auto','『국어』 187쪽 (3) — 어떻게 빛나고 싶은지 문장으로 쓴 것은?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":7,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"『국어』 187쪽 (3) — 어떻게 빛나고 싶은지 문장으로 쓴 것은?","options":[{"t":"부끄럽지만 용기를 내어 손을 들고 내 생각을 발표하는 별이 되고 싶어요.","correct":true},{"t":"별.","mis":"K1-2-u6-X01"},{"t":"반짝반짝.","mis":"K1-2-u6-X01"}],"explanation":["어떻게 빛나고 싶은지 문장으로 썼어요.","낱말 하나로는 생각이 드러나지 않아요.","187쪽 (3)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#8','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',2,'ox','auto','시 「반짝반짝」을 읽고 혼자 하는 일만 소중하다고 생각해야 해요.',ARRAY['K1-2-u6-X09']::text[],false,'{"seq":8,"concept":"K1-2-u6-C3","difficulty":2,"kind":"ox","stem":"시 「반짝반짝」을 읽고 혼자 하는 일만 소중하다고 생각해야 해요.","answer":"X","reason_options":[{"t":"혼자 하는 일도 함께 하는 일도 모두 소중하니까","correct":true},{"t":"여럿이 하는 일은 필요 없으니까","mis":"K1-2-u6-X09"}],"mis":"K1-2-u6-X09","explanation":["둘 다 소중해요.","혼자 빛나고, 모이면 더 빛나요.","지도서 250쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
