INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#10','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',3,'mc','auto','친구와 내가 쓴 문장이 서로 달라요. 알맞은 생각은?',ARRAY['K1-2-u6-X03']::text[],false,'{"seq":10,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"친구와 내가 쓴 문장이 서로 달라요. 알맞은 생각은?","options":[{"t":"친구 문장과 견주어 보며 다양한 생각을 알아봐요","correct":true},{"t":"내 문장만 맞아요","mis":"K1-2-u6-X03"},{"t":"친구 문장을 그대로 따라 고쳐요","mis":"K1-2-u6-X03"}],"explanation":["친구들이 쓴 문장과 비교해 봐요.","생각이 달라도 틀린 것이 아니에요.","지도서 250쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
