INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#9','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',4,'essay','teacher','『국어』 187쪽 (3) — 자신은 어떻게 빛나고 싶은지 「~하는 별(별자리)이 되고 싶어요.」로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"『국어』 187쪽 (3) — 자신은 어떻게 빛나고 싶은지 「~하는 별(별자리)이 되고 싶어요.」로 쓰세요.","answer_guide":{"answer":"예: 아침마다 친구들에게 먼저 인사하는 별이 되고 싶어요. — 무엇을 하며 빛나고 싶은지 문장으로 있으면 맞아요.","scoring_points":["어떻게 빛나고 싶은지 썼는가","별이나 별자리를 알맞게 골랐는가","완결된 문장인가"]},"explanation":["혼자인지 함께인지 생각해요.","무엇을 하며 빛나고 싶은지 써요.","187쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#10','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',4,'essay','teacher','『국어』 188쪽 — 우리 반이나 우리 학교를 위해 내가 할 수 있는 일을 짧은 문장 두 개로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"『국어』 188쪽 — 우리 반이나 우리 학교를 위해 내가 할 수 있는 일을 짧은 문장 두 개로 쓰세요.","answer_guide":{"answer":"예: 나는 급식을 먹고 내 자리를 닦겠어요. 친구가 무거운 것을 들면 함께 들겠어요. — 할 일이 짧은 문장 두 개로 있으면 맞아요.","scoring_points":["할 수 있는 일인가","짧은 문장 두 개로 썼는가","우리 반이나 학교를 위한 일인가"]},"explanation":["붙임딱지에 쓸 문장이에요.","모아서 우리 반 별자리를 만들어요.","188쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
