INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_challenge#4','kor',1,2,'u6','L06','g1_2_kor_u6_L06_challenge','lesson_challenge','K1-2-u6-C4',3,'error','auto','「같다」와 「갔다」는 소리가 같으니 뜻도 같다고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u6-X11','K1-2-u6-X10']::text[],false,'{"seq":4,"concept":"K1-2-u6-C4","difficulty":3,"kind":"error","stem":"「같다」와 「갔다」는 소리가 같으니 뜻도 같다고 했어요. 무엇이 잘못되었나요?","options":[{"t":"소리는 같아도 뜻이 달라요 — 「같다」는 똑같다, 「갔다」는 가다","correct":true,"mis_target":"K1-2-u6-X11"},{"t":"잘 말했어요","mis":"K1-2-u6-X11"},{"t":"소리도 서로 달라요","mis":"K1-2-u6-X10"}],"explanation":["소리가 같아도 글자가 다르면 뜻이 달라요.","그래서 바르게 구별해 써요.","190쪽 2번 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
