INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_challenge#10','kor',1,2,'u6','L06','g1_2_kor_u6_L06_challenge','lesson_challenge','K1-2-u6-C4',4,'essay','teacher','우리 교실이나 학교에서 소리와 글자가 다른 낱말을 하나 찾아, 소리와 바르게 쓴 글자를 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C4","difficulty":4,"kind":"essay","stem":"우리 교실이나 학교에서 소리와 글자가 다른 낱말을 하나 찾아, 소리와 바르게 쓴 글자를 함께 쓰세요.","answer_guide":{"answer":"예: 꽃밭 — 소리는 [꼳빧], 글자는 꽃밭. — 소리와 글자가 다른 낱말을 바르게 쓰면 맞아요.","scoring_points":["소리와 글자가 다른 낱말인가","소리를 [ ]로 썼는가","글자를 바르게 썼는가"]},"explanation":["안내판, 게시판을 살펴봐요.","지도서 252쪽처럼 주변에서 찾아요.","지도서 252쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#1','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 『국어』 191쪽 — 더 자연스럽게 들리는 읽기는?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":1,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 『국어』 191쪽 — 더 자연스럽게 들리는 읽기는?","options":[{"t":"소화전 근처에는 ∨ 주차하면 안 됩니다.","correct":true},{"t":"소화전근처에는주차하면안됩니다.","mis":"K1-2-u6-X14"},{"t":"소 ∨ 화 ∨ 전 ∨ 근 ∨ 처 ∨ 에 ∨ 는 ∨ 주차하면 안 됩니다.","mis":"K1-2-u6-X13"}],"explanation":["알맞게 띄어 읽었어요.","붙여 읽거나 글자마다 끊으면 뜻을 알기 어려워요.","지도서 255쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#2','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',1,'mc','auto','「소방관의 부탁」은 누가 하는 이야기인가요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":2,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"「소방관의 부탁」은 누가 하는 이야기인가요?","options":[{"t":"소방관","correct":true},{"t":"경찰관","mis":"K1-2-u6-X17"},{"t":"선생님","mis":"K1-2-u6-X17"}],"explanation":["소방서에서 일하는 소방관이에요.","지도서 257쪽 듣기 자료예요.","첫 줄을 떠올려요."],"asset":{"type":"passage","lines":["첫째, 소방서에 장난 전화를 하면 안 됩니다.","신고가 들어오면 소방관은 바로 출동해야 합니다.","그런데 만약 그 전화가 장난이라면","정말 도움이 필요한 다른 사람들에게 소방관이 갈 수 없게 됩니다."],"title":"「소방관의 부탁」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#3','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',1,'mc','auto','소방관이 첫째로 한 부탁은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":3,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"소방관이 첫째로 한 부탁은?","options":[{"t":"소방서에 장난 전화를 하지 말아 주세요","correct":true},{"t":"소방차를 구경하러 오세요","mis":"K1-2-u6-X17"},{"t":"소화전에 차를 대 주세요","mis":"K1-2-u6-X17"}],"explanation":["첫째는 장난 전화예요.","글에 없는 부탁은 고르지 않아요.","첫째 줄이에요."],"asset":{"type":"passage","lines":["첫째, 소방서에 장난 전화를 하면 안 됩니다.","신고가 들어오면 소방관은 바로 출동해야 합니다.","그런데 만약 그 전화가 장난이라면","정말 도움이 필요한 다른 사람들에게 소방관이 갈 수 없게 됩니다."],"title":"「소방관의 부탁」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#4','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',1,'mc','auto','『국어』 191쪽 2번 (2) — 소방서에 장난 전화를 하면 안 되는 까닭은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":4,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"『국어』 191쪽 2번 (2) — 소방서에 장난 전화를 하면 안 되는 까닭은?","options":[{"t":"정말 도움이 필요한 사람에게 소방관이 갈 수 없게 되어서","correct":true},{"t":"전화 요금이 많이 나와서","mis":"K1-2-u6-X17"},{"t":"소방관이 심심해서","mis":"K1-2-u6-X17"}],"explanation":["신고가 들어오면 바로 출동해야 해요.","191쪽 예시 답안이에요.","넷째 줄이에요."],"asset":{"type":"passage","lines":["첫째, 소방서에 장난 전화를 하면 안 됩니다.","신고가 들어오면 소방관은 바로 출동해야 합니다.","그런데 만약 그 전화가 장난이라면","정말 도움이 필요한 다른 사람들에게 소방관이 갈 수 없게 됩니다."],"title":"「소방관의 부탁」 (1)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#5','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','『국어』 191쪽 2번 (1) — 소방관이 차를 대지 말아 달라고 한 곳은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"『국어』 191쪽 2번 (1) — 소방관이 차를 대지 말아 달라고 한 곳은?","options":[{"t":"도로에 있는 소화전 근처","correct":true},{"t":"학교 운동장","mis":"K1-2-u6-X17"},{"t":"집 주차장","mis":"K1-2-u6-X17"}],"explanation":["소화전에서 물을 끌어다 써요.","그래서 근처에 차를 대면 안 돼요.","둘째 부탁이에요."],"asset":{"type":"passage","lines":["둘째, 도로에 있는 소화전 근처에는 차를 대면 안 됩니다.","소방차에는 많은 물을 가지고 다닐 수 없습니다.","그래서 도로에 물을 끌어다 쓸 수 있는 곳을 만들어 놓았지요.","부모님께서 소화전 근처에 주차하시지 않도록 꼭 말씀드려 주세요."],"title":"「소방관의 부탁」 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#6','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','불이 났을 때 소방관이 부탁한 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"불이 났을 때 소방관이 부탁한 것은?","options":[{"t":"구경하지 말고 건물에서 멀리 떨어진 곳으로 빠르게 대피해요","correct":true},{"t":"가까이 가서 구경해요","mis":"K1-2-u6-X17"},{"t":"건물 안에서 기다려요","mis":"K1-2-u6-X17"}],"explanation":["불에 탄 물건이 떨어질 수 있어요.","멀리 떨어진 곳으로 대피해요.","셋째 부탁이에요."],"asset":{"type":"passage","lines":["셋째, 불이 난 곳 근처에서 구경하지 말고 빠르게 대피해야 합니다.","건물에 불이 나면 불에 탄 물건이 머리 위로 떨어질 수도 있습니다.","불이 나면 모두의 안전을 위해 건물에서 멀리 떨어진 곳으로 대피해야 합니다."],"title":"「소방관의 부탁」 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#7','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',2,'ox','auto','『국어』 192쪽 — 「불이 나면…」 문장을 띄어 읽는 방법은 한 가지뿐이에요.',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":7,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"『국어』 192쪽 — 「불이 나면…」 문장을 띄어 읽는 방법은 한 가지뿐이에요.","answer":"X","reason_options":[{"t":"뜻이 통하면 여러 곳에서 띄어 읽을 수 있으니까","correct":true},{"t":"정답은 언제나 하나뿐이니까","mis":"K1-2-u6-X15"}],"mis":"K1-2-u6-X15","explanation":["두 가지 모두 뜻이 통해요.","한 가지 정답보다 뜻이 잘 드러나는 방법을 찾아요.","지도서 256쪽이에요."],"asset":{"type":"passage","lines":["첫 번째: 불이 나면 ∨ 모두의 안전을 위해 ∨ 건물에서 ∨ 멀리 떨어진 곳으로 ∨ 대피해야 합니다.","두 번째: 불이 나면 ∨ 모두의 안전을 위해 ∨ 건물에서 멀리 떨어진 곳으로 ∨ 대피해야 합니다."],"title":"『국어』 192쪽 — 두 가지 띄어 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#8','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','『국어』 192쪽 도움말 — 문장을 자연스럽게 읽으려면?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":8,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"『국어』 192쪽 도움말 — 문장을 자연스럽게 읽으려면?","options":[{"t":"글을 쓴 사람이 말하려는 내용을 떠올리며 읽어요","correct":true},{"t":"글자마다 끊어 읽어요","mis":"K1-2-u6-X13"},{"t":"쉬지 않고 빠르게 읽어요","mis":"K1-2-u6-X14"}],"explanation":["문장의 내용을 생각하며 읽어요.","글자마다 끊지 않아요.","192쪽 도움말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#9','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 『국어』 193쪽 4번 — 자연스럽게 띄어 읽지 않은 것은?',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":9,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 『국어』 193쪽 4번 — 자연스럽게 띄어 읽지 않은 것은?","options":[{"t":"신고가 들 ∨ 어오면 소방 ∨ 관은 바로 출동해야 합니다.","correct":true},{"t":"신고가 들어오면 ∨ 소방관은 ∨ 바로 출동해야 합니다.","mis":"K1-2-u6-X15"},{"t":"신고가 들어오면 ∨ 소방관은 바로 출동해야 합니다.","mis":"K1-2-u6-X15"}],"explanation":["낱말 가운데에서 끊으면 뜻이 끊겨요.","나머지 둘은 쉬는 곳이 달라도 뜻이 통해요.","193쪽 4번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#10','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',3,'mc','auto','지도서 255쪽 — 글을 바르게 띄어 읽지 않으면 어떻게 될까요?',ARRAY['K1-2-u6-X17','K1-2-u6-X14']::text[],false,'{"seq":10,"concept":"K1-2-u6-C5","difficulty":3,"kind":"mc","stem":"지도서 255쪽 — 글을 바르게 띄어 읽지 않으면 어떻게 될까요?","options":[{"t":"문장의 뜻을 잘못 이해할 수 있어요","correct":true},{"t":"글자가 바뀌어요","mis":"K1-2-u6-X17"},{"t":"아무 일도 없어요","mis":"K1-2-u6-X14"}],"explanation":["띄어 읽기는 뜻을 바르게 전해요.","그래서 알맞게 띄어 읽어요.","지도서 255쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#1','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',2,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 『국어활동』 65쪽 — 「귓속을 청소하기도 하지요.」를 자연스럽게 읽은 것은?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":1,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 『국어활동』 65쪽 — 「귓속을 청소하기도 하지요.」를 자연스럽게 읽은 것은?","options":[{"t":"귓속을 ∨ 청소하기도 하지요.","correct":true},{"t":"귓속을 청소 ∨ 하기도 하지요.","mis":"K1-2-u6-X13"},{"t":"귓속을청소하기도하지요.","mis":"K1-2-u6-X14"}],"explanation":["「청소하기도」는 한 덩어리예요.","붙이거나 덩어리를 가르면 어색해요.","국어활동 65쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
