INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#3','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',3,'error','auto','「불이 나면…」을 두 번째 방법으로 읽었더니 다른 친구가 「틀렸어.」라고 했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":3,"concept":"K1-2-u6-C5","difficulty":3,"kind":"error","stem":"「불이 나면…」을 두 번째 방법으로 읽었더니 다른 친구가 「틀렸어.」라고 했어요. 무엇이 잘못되었나요?","options":[{"t":"두 번째 방법도 뜻이 통해요 — 띄어 읽는 곳은 여러 가지예요","correct":true,"mis_target":"K1-2-u6-X15"},{"t":"「틀렸어.」가 맞아요","mis":"K1-2-u6-X15"},{"t":"첫 번째만 정답이에요","mis":"K1-2-u6-X15"}],"explanation":["두 방법 모두 뜻이 통해요.","친구의 띄어 읽기도 존중해요.","지도서 245쪽이에요."],"asset":{"type":"passage","lines":["첫 번째: 불이 나면 ∨ 모두의 안전을 위해 ∨ 건물에서 ∨ 멀리 떨어진 곳으로 ∨ 대피해야 합니다.","두 번째: 불이 나면 ∨ 모두의 안전을 위해 ∨ 건물에서 멀리 떨어진 곳으로 ∨ 대피해야 합니다."],"title":"『국어』 192쪽 — 두 가지 띄어 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
