INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#5','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',3,'mc','auto','지도서 245쪽 — 띄어 쓴 곳마다 모두 쉬어 읽으면 어떻게 들릴까요?',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":3,"kind":"mc","stem":"지도서 245쪽 — 띄어 쓴 곳마다 모두 쉬어 읽으면 어떻게 들릴까요?","options":[{"t":"뚝뚝 끊겨 부자연스럽게 들려요","correct":true},{"t":"가장 자연스럽게 들려요","mis":"K1-2-u6-X15"},{"t":"뜻이 더 잘 통해요","mis":"K1-2-u6-X15"}],"explanation":["기계적으로 띄어 읽지 않아요.","뜻이 이어지는 덩어리로 읽어요.","지도서 245쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#6','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',3,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 「개구리는 혀로 날아다니는 벌레를 잡아먹습니다.」를 자연스럽게 읽은 것은?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":6,"concept":"K1-2-u6-C5","difficulty":3,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 「개구리는 혀로 날아다니는 벌레를 잡아먹습니다.」를 자연스럽게 읽은 것은?","options":[{"t":"개구리는 ∨ 혀로 ∨ 날아다니는 벌레를 ∨ 잡아먹습니다.","correct":true},{"t":"개구리는 혀로 날아다 ∨ 니는 벌레를 잡아 ∨ 먹습니다.","mis":"K1-2-u6-X13"},{"t":"개구리는혀로날아다니는벌레를잡아먹습니다.","mis":"K1-2-u6-X14"}],"explanation":["뜻이 이어지는 곳에서 쉬었어요.","낱말을 자르거나 붙이면 어색해요.","국어활동 65쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#7','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',3,'mc','auto','지도서 255쪽 — 쉬지 않고 빠르게 읽은 ㉮를 들으면 어떤가요?',ARRAY['K1-2-u6-X14']::text[],false,'{"seq":7,"concept":"K1-2-u6-C5","difficulty":3,"kind":"mc","stem":"지도서 255쪽 — 쉬지 않고 빠르게 읽은 ㉮를 들으면 어떤가요?","options":[{"t":"뜻을 알아듣기 어려워요","correct":true},{"t":"더 자연스럽게 들려요","mis":"K1-2-u6-X14"},{"t":"뜻이 더 잘 통해요","mis":"K1-2-u6-X14"}],"explanation":["붙여 읽으면 듣는 사람이 힘들어요.","알맞게 띄어 읽어요.","지도서 255쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#8','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',4,'sa','auto','「소방관의 부탁」에서 소방차가 물을 끌어다 쓰는 곳으로, 근처에 차를 대면 안 되는 곳을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u6-C5","difficulty":4,"kind":"sa","stem":"「소방관의 부탁」에서 소방차가 물을 끌어다 쓰는 곳으로, 근처에 차를 대면 안 되는 곳을 쓰세요.","answer":["소화전"],"explanation":["소화전 근처에 차를 대면 안 돼요.","소방차는 그곳에서 물을 끌어다 써요.","둘째 부탁이에요."],"asset":{"type":"passage","lines":["둘째, 도로에 있는 소화전 근처에는 차를 대면 안 됩니다.","소방차에는 많은 물을 가지고 다닐 수 없습니다.","그래서 도로에 물을 끌어다 쓸 수 있는 곳을 만들어 놓았지요.","부모님께서 소화전 근처에 주차하시지 않도록 꼭 말씀드려 주세요."],"title":"「소방관의 부탁」 (2)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#9','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',4,'essay','teacher','(∨ 는 쉬어 읽는 곳이에요.) 「소방관들이 위험에 처한 사람들을 도울 수 있게 장난 전화를 하지 말아 주세요.」를 뜻이 잘 통하게 ∨ 를 넣어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C5","difficulty":4,"kind":"essay","stem":"(∨ 는 쉬어 읽는 곳이에요.) 「소방관들이 위험에 처한 사람들을 도울 수 있게 장난 전화를 하지 말아 주세요.」를 뜻이 잘 통하게 ∨ 를 넣어 쓰세요.","answer_guide":{"answer":"예: 소방관들이 ∨ 위험에 처한 사람들을 ∨ 도울 수 있게 ∨ 장난 전화를 하지 말아 주세요. — 낱말 가운데를 자르지 않고 뜻이 통하면 맞아요.","scoring_points":["낱말 가운데에서 쉬지 않았는가","뜻이 통하는 덩어리로 나누었는가","글자마다 끊지 않았는가"]},"explanation":["정답은 하나가 아니에요.","뜻이 잘 드러나게 나누어요.","지도서 257쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#10','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',4,'essay','teacher','친구와 띄어 읽은 곳이 달랐어요. 친구에게 할 말을 한두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C5","difficulty":4,"kind":"essay","stem":"친구와 띄어 읽은 곳이 달랐어요. 친구에게 할 말을 한두 문장으로 쓰세요.","answer_guide":{"answer":"예: 너는 거기서 쉬었구나. 나와 달라도 뜻이 잘 통해. — 친구의 띄어 읽기를 존중하는 말이면 맞아요.","scoring_points":["친구의 읽기를 존중했는가","뜻이 통하는지 말했는가","완결된 문장인가"]},"explanation":["쉬는 곳은 여러 가지일 수 있어요.","서로 들려주며 견주어요.","193쪽 4번 (3)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#1','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',1,'mc','auto','「괜찮아 아저씨」에서 아저씨가 아침마다 한 일은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":1,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"「괜찮아 아저씨」에서 아저씨가 아침마다 한 일은?","options":[{"t":"세수를 하고 머리 모양을 만들었어요","correct":true},{"t":"머리카락을 모두 잘랐어요","mis":"K1-2-u6-X17"},{"t":"모자를 샀어요","mis":"K1-2-u6-X17"}],"explanation":["아침마다 머리 모양을 만들었어요.","글에 없는 일은 고르지 않아요.","196쪽이에요."],"asset":{"type":"passage","lines":["아저씨는 아침마다 세수를 하고 머리 모양을 만들어요.","머리카락은 처음에 열 올이었어요.","새·거미·곰·토끼를 만날 때마다 한 올씩 쏘옥 빠져요.","아저씨는 남은 머리카락을 묶고, 가르마를 타고, 말고, 땋았어요.","그리고 늘 이렇게 말해요. “오, 괜찮은데?”"],"title":"「괜찮아 아저씨」(김경희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#2','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',1,'mc','auto','아저씨의 머리카락은 처음에 몇 올이었나요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":2,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"아저씨의 머리카락은 처음에 몇 올이었나요?","options":[{"t":"열 올","correct":true},{"t":"다섯 올","mis":"K1-2-u6-X17"},{"t":"스무 올","mis":"K1-2-u6-X17"}],"explanation":["처음에는 열 올이었어요.","197쪽 그림에서 하나부터 열까지 세어요.","197쪽이에요."],"asset":{"type":"passage","lines":["아저씨는 아침마다 세수를 하고 머리 모양을 만들어요.","머리카락은 처음에 열 올이었어요.","새·거미·곰·토끼를 만날 때마다 한 올씩 쏘옥 빠져요.","아저씨는 남은 머리카락을 묶고, 가르마를 타고, 말고, 땋았어요.","그리고 늘 이렇게 말해요. “오, 괜찮은데?”"],"title":"「괜찮아 아저씨」(김경희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#3','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',1,'mc','auto','지도서 259쪽 — 머리카락을 셀 때 쓰는 말로 알맞은 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":3,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"지도서 259쪽 — 머리카락을 셀 때 쓰는 말로 알맞은 것은?","options":[{"t":"올","correct":true},{"t":"마리","mis":"K1-2-u6-X17"},{"t":"그루","mis":"K1-2-u6-X17"}],"explanation":["머리카락이나 실은 올·가닥으로 세요.","마리는 동물, 그루는 나무예요.","지도서 259쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#4','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',1,'mc','auto','아저씨가 머리 모양을 만들고 늘 한 말은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":4,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"아저씨가 머리 모양을 만들고 늘 한 말은?","options":[{"t":"“오, 괜찮은데?”","correct":true},{"t":"“아, 속상해.”","mis":"K1-2-u6-X17"},{"t":"“다시는 안 할래.”","mis":"K1-2-u6-X17"}],"explanation":["늘 「오, 괜찮은데?」라고 했어요.","밝은 마음이 담겨 있어요.","되풀이되는 말이에요."],"asset":{"type":"passage","lines":["아저씨는 아침마다 세수를 하고 머리 모양을 만들어요.","머리카락은 처음에 열 올이었어요.","새·거미·곰·토끼를 만날 때마다 한 올씩 쏘옥 빠져요.","아저씨는 남은 머리카락을 묶고, 가르마를 타고, 말고, 땋았어요.","그리고 늘 이렇게 말해요. “오, 괜찮은데?”"],"title":"「괜찮아 아저씨」(김경희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#5','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'match','auto','『국어』 198~204쪽 — 만난 것과 그때 모습을 나타내는 말을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"『국어』 198~204쪽 — 만난 것과 그때 모습을 나타내는 말을 이어 보세요.","pairs":[{"l":"새들","r":"포르르"},{"l":"거미","r":"흔들흔들"},{"l":"곰과 시소","r":"오르락내리락"}],"mis":"K1-2-u6-X17","explanation":["흉내 내는 말이 장면을 그려 줘요.","장면마다 한 올씩 빠졌어요.","지도서 262쪽이에요."],"asset":{"type":"passage","lines":["낮잠을 자는데 새들이 포르르 — 한 올이 쏘옥","비 오는 날 거미가 흔들흔들 — 한 올이 쏘옥","곰이랑 시소를 오르락내리락 — 한 올이 쏘옥","토끼랑 깡충깡충 달리기 — 한 올이 쏘옥"],"title":"『국어』 198~204쪽 — 머리카락이 빠진 까닭(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#6','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'mc','auto','아홉 올일 때 아저씨는 머리카락을 어떻게 했나요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":2,"kind":"mc","stem":"아홉 올일 때 아저씨는 머리카락을 어떻게 했나요?","options":[{"t":"세 개씩 묶었어요","correct":true},{"t":"땋았어요","mis":"K1-2-u6-X17"},{"t":"가르마를 탔어요","mis":"K1-2-u6-X17"}],"explanation":["아홉 올을 세 개씩 묶었어요.","199쪽 그림이에요.","글과 그림을 함께 봐요."],"asset":{"type":"passage","lines":["아홉 올 — 세 개씩 묶었어요.","여덟 올 — 가르마를 탔어요.","일곱 올 — 꼬불꼬불 말았어요.","여섯 올 — 땋았어요."],"title":"『국어』 199~205쪽 — 머리카락 수와 머리 모양"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#7','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'mc','auto','『국어』 206쪽 (2) — 아저씨가 「오, 괜찮은데?」라고 말한 까닭은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":7,"concept":"K1-2-u6-C6","difficulty":2,"kind":"mc","stem":"『국어』 206쪽 (2) — 아저씨가 「오, 괜찮은데?」라고 말한 까닭은?","options":[{"t":"남은 머리카락으로 바꾼 자신의 모습이 마음에 들어서","correct":true},{"t":"머리카락이 다시 자라서","mis":"K1-2-u6-X17"},{"t":"새들이 머리카락을 돌려줘서","mis":"K1-2-u6-X17"}],"explanation":["바뀐 모습이 마음에 들었어요.","문제를 밝게 받아들이는 마음이에요.","206쪽 예시 답안이에요."],"asset":{"type":"passage","lines":["아저씨는 아침마다 세수를 하고 머리 모양을 만들어요.","머리카락은 처음에 열 올이었어요.","새·거미·곰·토끼를 만날 때마다 한 올씩 쏘옥 빠져요.","아저씨는 남은 머리카락을 묶고, 가르마를 타고, 말고, 땋았어요.","그리고 늘 이렇게 말해요. “오, 괜찮은데?”"],"title":"「괜찮아 아저씨」(김경희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#8','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'ox','auto','이 작품은 글과 그림을 함께 보아야 아저씨의 머리 모양을 잘 알 수 있어요.',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":8,"concept":"K1-2-u6-C6","difficulty":2,"kind":"ox","stem":"이 작품은 글과 그림을 함께 보아야 아저씨의 머리 모양을 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"머리 모양은 그림에 자세히 나오니까","correct":true},{"t":"그림은 보지 않아도 되니까","mis":"K1-2-u6-X17"}],"mis":"K1-2-u6-X17","explanation":["글과 그림이 서로 보완해요.","번갈아 읽어요.","지도서 259쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#9','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 『국어』 206쪽 — 더 자연스럽게 읽은 것은?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":9,"concept":"K1-2-u6-C6","difficulty":2,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 『국어』 206쪽 — 더 자연스럽게 읽은 것은?","options":[{"t":"아저씨는 ∨ 아침이면 ∨ 세수를 하고 ∨ 머리 모양을 만들었지요.","correct":true},{"t":"아 ∨ 저 ∨ 씨 ∨ 는 ∨ 아 ∨ 침 ∨ 이 ∨ 면","mis":"K1-2-u6-X13"},{"t":"아저씨는아침이면세수를하고머리모양을만들었지요.","mis":"K1-2-u6-X14"}],"explanation":["뜻이 통하는 덩어리로 읽었어요.","글자마다 끊거나 붙이면 어색해요.","지도서 262쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#10','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',3,'mc','auto','지도서 258쪽 — 「아저씨는 머리카락 숫자를 세었어요.」에서 조금 쉬어 읽으면 좋은 곳은?',ARRAY['K1-2-u6-X13','K1-2-u6-X16']::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"지도서 258쪽 — 「아저씨는 머리카락 숫자를 세었어요.」에서 조금 쉬어 읽으면 좋은 곳은?","options":[{"t":"「아저씨는」 뒤","correct":true},{"t":"「머리」 뒤","mis":"K1-2-u6-X13"},{"t":"어디에서도 쉬지 않아요","mis":"K1-2-u6-X16"}],"explanation":["「누가」에 해당하는 말 뒤에서 조금 쉬어요.","낱말 가운데에서는 쉬지 않아요.","지도서 258쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
