INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#3','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'error','auto','친구가 「아저씨는 머리카락이 빠져서 늘 슬퍼했다.」라고 정리했어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":3,"concept":"K1-2-u6-C6","difficulty":3,"kind":"error","stem":"친구가 「아저씨는 머리카락이 빠져서 늘 슬퍼했다.」라고 정리했어요. 무엇이 잘못되었나요?","options":[{"t":"아저씨는 「오, 괜찮은데?」 하며 밝게 받아들였어요","correct":true,"mis_target":"K1-2-u6-X17"},{"t":"잘 정리했어요","mis":"K1-2-u6-X17"},{"t":"머리카락이 늘어났어요","mis":"K1-2-u6-X17"}],"explanation":["글과 다르게 정리했어요.","아저씨의 말을 다시 읽어요.","206쪽이에요."],"asset":{"type":"passage","lines":["아저씨는 아침마다 세수를 하고 머리 모양을 만들어요.","머리카락은 처음에 열 올이었어요.","새·거미·곰·토끼를 만날 때마다 한 올씩 쏘옥 빠져요.","아저씨는 남은 머리카락을 묶고, 가르마를 타고, 말고, 땋았어요.","그리고 늘 이렇게 말해요. “오, 괜찮은데?”"],"title":"「괜찮아 아저씨」(김경희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#4','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'error','auto','「포르르, 흔들흔들, 깡충깡충」을 글자마다 끊어 힘없이 읽었어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":4,"concept":"K1-2-u6-C6","difficulty":3,"kind":"error","stem":"「포르르, 흔들흔들, 깡충깡충」을 글자마다 끊어 힘없이 읽었어요. 무엇이 아쉬운가요?","options":[{"t":"흉내 내는 말은 한 덩어리로 살려 읽어야 장면이 생생해져요","correct":true,"mis_target":"K1-2-u6-X13"},{"t":"잘 읽었어요","mis":"K1-2-u6-X13"},{"t":"더 빨리 붙여 읽어야 해요","mis":"K1-2-u6-X14"}],"explanation":["흉내 내는 말을 살려 읽어요.","글자마다 끊지 않아요.","지도서 262쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#5','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'mc','auto','머리카락 수가 어떻게 달라졌나요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":5,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"머리카락 수가 어떻게 달라졌나요?","options":[{"t":"열 → 아홉 → 여덟 → 일곱 → 여섯으로 한 올씩 줄었어요","correct":true},{"t":"한 올씩 늘었어요","mis":"K1-2-u6-X17"},{"t":"두 올씩 줄었어요","mis":"K1-2-u6-X17"}],"explanation":["장면마다 한 올씩 빠졌어요.","소리 내어 세어 봐요.","지도서 259쪽이에요."],"asset":{"type":"passage","lines":["아홉 올 — 세 개씩 묶었어요.","여덟 올 — 가르마를 탔어요.","일곱 올 — 꼬불꼬불 말았어요.","여섯 올 — 땋았어요."],"title":"『국어』 199~205쪽 — 머리카락 수와 머리 모양"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#6','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'mc','auto','지도서 262쪽 — 아홉 올을 세 개씩 묶으면 몇 묶음인가요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"지도서 262쪽 — 아홉 올을 세 개씩 묶으면 몇 묶음인가요?","options":[{"t":"세 묶음","correct":true},{"t":"두 묶음","mis":"K1-2-u6-X17"},{"t":"네 묶음","mis":"K1-2-u6-X17"}],"explanation":["세 올씩 세 묶음이에요.","그림에서 묶음을 세어요.","지도서 262쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#7','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'mc','auto','지도서 258쪽 — 문장과 문장 사이에서는 어떻게 읽나요?',ARRAY['K1-2-u6-X16','K1-2-u6-X13']::text[],false,'{"seq":7,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"지도서 258쪽 — 문장과 문장 사이에서는 어떻게 읽나요?","options":[{"t":"조금 더 쉬었다가 다음 문장을 읽어요","correct":true},{"t":"쉬지 않고 붙여 읽어요","mis":"K1-2-u6-X16"},{"t":"다음 낱말 가운데에서 쉬어요","mis":"K1-2-u6-X13"}],"explanation":["문장 사이에서는 조금 더 쉬어요.","붙이거나 낱말을 자르지 않아요.","지도서 258쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#8','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',4,'sa','auto','아저씨가 여섯 올 남은 머리카락으로 한 일을 쓰세요. 「머리카락을 (  ).」','{}'::text[],false,'{"seq":8,"concept":"K1-2-u6-C6","difficulty":4,"kind":"sa","stem":"아저씨가 여섯 올 남은 머리카락으로 한 일을 쓰세요. 「머리카락을 (  ).」","answer":["땋았어요","땋았다","땋다"],"explanation":["여섯 올은 땋았어요.","205쪽 그림이에요.","글과 그림을 함께 봐요."],"asset":{"type":"passage","lines":["아홉 올 — 세 개씩 묶었어요.","여덟 올 — 가르마를 탔어요.","일곱 올 — 꼬불꼬불 말았어요.","여섯 올 — 땋았어요."],"title":"『국어』 199~205쪽 — 머리카락 수와 머리 모양"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#9','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',4,'essay','teacher','『국어』 207쪽 (1) — 머리카락이 다섯 올일 때 아저씨의 머리 모양을 상상해서 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C6","difficulty":4,"kind":"essay","stem":"『국어』 207쪽 (1) — 머리카락이 다섯 올일 때 아저씨의 머리 모양을 상상해서 문장으로 쓰세요.","answer_guide":{"answer":"예: 다섯 올을 모두 위로 세워 왕관처럼 만들었을 것 같아요. — 다섯 올로 만든 모양이 드러나면 맞아요.","scoring_points":["다섯 올로 만든 모양인가","상상한 모습이 드러나는가","완결된 문장인가"]},"explanation":["앞의 머리 모양을 떠올려요.","친구와 견주어 봐요.","207쪽 (1)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#10','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',4,'essay','teacher','『국어』 207쪽 (3) — 아저씨께 해 주고 싶은 말을 까닭과 함께 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":4,"kind":"essay","stem":"『국어』 207쪽 (3) — 아저씨께 해 주고 싶은 말을 까닭과 함께 문장으로 쓰세요.","answer_guide":{"answer":"예: 아저씨, 머리카락이 줄어도 늘 웃어서 멋져요! — 머리 모양이나 아저씨의 마음과 관련된 말이면 맞아요.","scoring_points":["아저씨께 하는 말인가","까닭이나 생각이 있는가","완결된 문장인가"]},"explanation":["머리 모양을 보고 떠오른 생각을 써요.","「오, 괜찮은데?」의 마음을 떠올려요.","207쪽 (3)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#1','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',1,'mc','auto','『국어』 208쪽 대본 — 공작새가 부러워한 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":1,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"『국어』 208쪽 대본 — 공작새가 부러워한 것은?","options":[{"t":"꾀꼬리의 아름다운 목소리","correct":true},{"t":"꾀꼬리의 깃털","mis":"K1-2-u6-X17"},{"t":"하늘의 구름","mis":"K1-2-u6-X17"}],"explanation":["공작새는 꾀꼬리의 목소리를 부러워했어요.","첫 줄이에요.","대본을 읽어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#2','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',1,'mc','auto','꾀꼬리가 알려 준 공작새의 좋은 점은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":2,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"꾀꼬리가 알려 준 공작새의 좋은 점은?","options":[{"t":"아름다운 깃털","correct":true},{"t":"예쁜 목소리","mis":"K1-2-u6-X17"},{"t":"빠른 다리","mis":"K1-2-u6-X17"}],"explanation":["「너에게는 아름다운 깃털이 있잖아.」","꾀꼬리의 말이에요.","둘째 줄이에요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#3','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',1,'mc','auto','목소리 연극 「공작새」에 나오지 않는 인물은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":3,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"목소리 연극 「공작새」에 나오지 않는 인물은?","options":[{"t":"호랑이","correct":true},{"t":"꾀꼬리","mis":"K1-2-u6-X17"},{"t":"하늘","mis":"K1-2-u6-X17"}],"explanation":["공작새, 꾀꼬리, 하늘이 나와요.","호랑이는 다른 대본이에요.","208쪽이에요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#4','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',1,'mc','auto','「공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!」는 어떻게 읽나요?',ARRAY['K1-2-u6-X18']::text[],false,'{"seq":4,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"「공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!」는 어떻게 읽나요?","options":[{"t":"느낌표를 살려 힘 있게 읽어요","correct":true},{"t":"끝을 올려 물어보듯 읽어요","mis":"K1-2-u6-X18"},{"t":"아주 작게 속삭여요","mis":"K1-2-u6-X18"}],"explanation":["느낌표는 힘주어 읽어요.","문장 부호에 따라 읽어요.","지도서 264쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#5','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',2,'mc','auto','하늘이 깃털 대신 목소리를 주겠다고 하자 공작새는?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":5,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"하늘이 깃털 대신 목소리를 주겠다고 하자 공작새는?","options":[{"t":"깜짝 놀라 그건 안 된다고 외쳤어요","correct":true},{"t":"기뻐하며 고맙다고 했어요","mis":"K1-2-u6-X17"},{"t":"아무 말도 하지 않았어요","mis":"K1-2-u6-X17"}],"explanation":["깃털은 그대로 두고 싶었어요.","넷째 줄이에요.","대본을 읽어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#6','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',2,'mc','auto','하늘이 마지막에 한 말의 뜻은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"하늘이 마지막에 한 말의 뜻은?","options":[{"t":"남을 부러워하기보다 자신의 좋은 점을 잘 살려요","correct":true},{"t":"욕심을 많이 낼수록 좋아요","mis":"K1-2-u6-X17"},{"t":"다른 친구의 것을 가져와요","mis":"K1-2-u6-X17"}],"explanation":["자신의 좋은 점을 살려요.","마지막 줄이에요.","대본을 읽어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#7','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',2,'mc','auto','지도서 265쪽 — 친구의 목소리 연극을 평가할 때 살펴볼 것은?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"지도서 265쪽 — 친구의 목소리 연극을 평가할 때 살펴볼 것은?","options":[{"t":"문장을 자연스럽게 읽고 있는지","correct":true},{"t":"친구의 외모가 어떤지","mis":"K1-2-u6-X19"},{"t":"누가 가장 빨리 끝냈는지","mis":"K1-2-u6-X19"}],"explanation":["자연스럽게 읽는지에 초점을 둬요.","외모나 말버릇은 평가하지 않아요.","지도서 265쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#8','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',2,'ox','auto','친구가 발표할 때에는 장난스럽지 않게 진지하게 들어요.',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":8,"concept":"K1-2-u6-C7","difficulty":2,"kind":"ox","stem":"친구가 발표할 때에는 장난스럽지 않게 진지하게 들어요.","answer":"O","reason_options":[{"t":"발표하는 친구가 위축되지 않으니까","correct":true},{"t":"친구가 틀리면 웃어도 되니까","mis":"K1-2-u6-X19"}],"mis":"K1-2-u6-X19","explanation":["진지한 분위기로 들어요.","발표하는 친구를 배려해요.","지도서 265쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
