INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#1','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',2,'mc','auto','공작새가 하늘에 바란 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":1,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"공작새가 하늘에 바란 것은?","options":[{"t":"지금 모습에서 목소리만 더 예뻐지는 것","correct":true},{"t":"깃털을 버리는 것","mis":"K1-2-u6-X17"},{"t":"하늘을 나는 것","mis":"K1-2-u6-X17"}],"explanation":["깃털도 지키고 목소리도 원했어요.","공작새의 대사예요.","대본을 읽어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
