INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#3','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'error','auto','친구의 목소리 연극 평가지에 「옷이 예뻤어요.」라고 썼어요. 무엇이 잘못되었나요?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":3,"concept":"K1-2-u6-C7","difficulty":3,"kind":"error","stem":"친구의 목소리 연극 평가지에 「옷이 예뻤어요.」라고 썼어요. 무엇이 잘못되었나요?","options":[{"t":"외모가 아니라 문장을 자연스럽게 읽었는지 평가해요","correct":true,"mis_target":"K1-2-u6-X19"},{"t":"잘 썼어요","mis":"K1-2-u6-X19"},{"t":"목소리 크기만 쓰면 돼요","mis":"K1-2-u6-X19"}],"explanation":["읽기에 대한 것을 평가해요.","외모는 평가하지 않아요.","지도서 265쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#4','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'error','auto','「그건 안 돼요.」를 끝을 올려 물어보듯 읽었어요. 무엇이 아쉬운가요?',ARRAY['K1-2-u6-X18','K1-2-u6-X19']::text[],false,'{"seq":4,"concept":"K1-2-u6-C7","difficulty":3,"kind":"error","stem":"「그건 안 돼요.」를 끝을 올려 물어보듯 읽었어요. 무엇이 아쉬운가요?","options":[{"t":"마침표 문장이에요 — 놀란 마음을 담아 끝맺어 읽어요","correct":true,"mis_target":"K1-2-u6-X18"},{"t":"잘 읽었어요","mis":"K1-2-u6-X18"},{"t":"더 빠르게 읽어야 해요","mis":"K1-2-u6-X19"}],"explanation":["마침표는 끝맺어 읽어요.","물어보는 말이 아니에요.","208쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#5','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'mc','auto','지도서 264쪽 — 인물의 마음을 짐작하며 읽으면 좋은 점은?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":5,"concept":"K1-2-u6-C7","difficulty":3,"kind":"mc","stem":"지도서 264쪽 — 인물의 마음을 짐작하며 읽으면 좋은 점은?","options":[{"t":"더 생동감 있게 대사를 읽을 수 있어요","correct":true},{"t":"대사를 외우지 않아도 돼요","mis":"K1-2-u6-X19"},{"t":"친구보다 빨리 끝낼 수 있어요","mis":"K1-2-u6-X19"}],"explanation":["마음을 생각하면 실감 나요.","빠르기는 중요하지 않아요.","지도서 264쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#6','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'mc','auto','지도서 266쪽 — 호랑이가 자신이 왕이라고 한 까닭은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C7","difficulty":3,"kind":"mc","stem":"지도서 266쪽 — 호랑이가 자신이 왕이라고 한 까닭은?","options":[{"t":"가장 힘이 세고 빠르게 달릴 수 있어서","correct":true},{"t":"하늘을 날 수 있어서","mis":"K1-2-u6-X17"},{"t":"높은 나무에 매달릴 수 있어서","mis":"K1-2-u6-X17"}],"explanation":["호랑이의 대사예요.","하늘은 독수리, 나무는 원숭이예요.","지도서 266쪽이에요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"내가 왕이야. 나는 여기에서 가장 힘이 세고 빠르게 달릴 수 있어."},{"who":"원숭이","text":"힘만 세면 다니? 나는 긴 두 팔로 높은 나무에 매달릴 수 있단다."},{"who":"악어","text":"과연 그럴까? 나에게 한번 물리면 절대 벗어날 수 없어!"},{"who":"독수리","text":"아무리 빠르고 힘이 세도 하늘을 나는 나를 이길 수 있을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#7','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'mc','auto','지도서 266쪽 — 독수리가 내세운 자신의 좋은 점은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":3,"kind":"mc","stem":"지도서 266쪽 — 독수리가 내세운 자신의 좋은 점은?","options":[{"t":"하늘을 날 수 있어요","correct":true},{"t":"긴 두 팔로 나무에 매달려요","mis":"K1-2-u6-X17"},{"t":"물리면 절대 벗어날 수 없어요","mis":"K1-2-u6-X17"}],"explanation":["독수리는 하늘을 날아요.","팔은 원숭이, 무는 것은 악어예요.","지도서 266쪽이에요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"내가 왕이야. 나는 여기에서 가장 힘이 세고 빠르게 달릴 수 있어."},{"who":"원숭이","text":"힘만 세면 다니? 나는 긴 두 팔로 높은 나무에 매달릴 수 있단다."},{"who":"악어","text":"과연 그럴까? 나에게 한번 물리면 절대 벗어날 수 없어!"},{"who":"독수리","text":"아무리 빠르고 힘이 세도 하늘을 나는 나를 이길 수 있을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#8','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',4,'sa','auto','공작새에게 「아름다운 깃털이 있잖아.」라고 말한 새의 이름을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u6-C7","difficulty":4,"kind":"sa","stem":"공작새에게 「아름다운 깃털이 있잖아.」라고 말한 새의 이름을 쓰세요.","answer":["꾀꼬리"],"explanation":["꾀꼬리가 말했어요.","공작새는 꾀꼬리의 목소리를 부러워했어요.","208쪽이에요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#9','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C1',4,'essay','teacher','지도서 266쪽 — 동물의 왕은 어떤 동물인지 자신의 생각을 까닭과 함께 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"지도서 266쪽 — 동물의 왕은 어떤 동물인지 자신의 생각을 까닭과 함께 문장으로 쓰세요.","answer_guide":{"answer":"예: 동물의 왕은 사자이다. 왜냐하면 힘이 가장 세고 달리기도 빠르기 때문이다. — 동물과 까닭이 있으면 맞아요.","scoring_points":["어떤 동물인지 썼는가","까닭을 썼는가","완결된 문장인가"]},"explanation":["생각과 까닭을 함께 써요.","친구 생각과 달라도 괜찮아요.","지도서 266쪽 활동 예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#10','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',4,'essay','teacher','목소리 연극을 마친 뒤 스스로 평가해요. 자신의 읽기에서 잘한 점과 아쉬운 점을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C7","difficulty":4,"kind":"essay","stem":"목소리 연극을 마친 뒤 스스로 평가해요. 자신의 읽기에서 잘한 점과 아쉬운 점을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 느낌표를 살려 힘 있게 읽었어요. / 아쉬운 점 — 긴 대사에서 낱말 가운데를 끊었어요. — 읽기에 대한 잘한 점과 아쉬운 점이 있으면 맞아요.","scoring_points":["읽기에 대한 잘한 점인가","읽기에 대한 아쉬운 점인가","완결된 문장인가"]},"explanation":["점검표처럼 스스로 돌아봐요.","외모가 아니라 읽기를 살펴요.","지도서 265쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#1','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C1',1,'mc','auto','『국어』 180쪽 — 그림 속 친구에게 해 주고 싶은 말로 알맞은 것은?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"『국어』 180쪽 — 그림 속 친구에게 해 주고 싶은 말로 알맞은 것은?","options":[{"t":"영화에 나오는 장면을 휴대 전화로 찍으면 안 돼.","correct":true},{"t":"싫어.","mis":"K1-2-u6-X01"},{"t":"나가.","mis":"K1-2-u6-X02"}],"explanation":["무엇을 하면 안 되는지 문장으로 말했어요.","한마디로는 생각이 전해지지 않아요.","180쪽이에요."],"asset":{"type":"scene","icon":"📱🎬","text":"영화관에서 한 친구가 영화 장면을 휴대 전화로 찍어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#2','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C2',1,'mc','auto','『국어』 185쪽 보기에서 「해결 방법」 칸에 쓴 것은?',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"『국어』 185쪽 보기에서 「해결 방법」 칸에 쓴 것은?","options":[{"t":"종이의 뒷면을 써요.","correct":true},{"t":"더 쓸 수 있는 종이를 버리려고 해요.","mis":"K1-2-u6-X06"},{"t":"아직 더 쓸 수 있으니까 종이의 뒷면도 쓰면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["둘째 칸이에요.","첫째는 문제, 셋째는 자신의 생각이에요.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 더 쓸 수 있는 종이를 버리려고 해요.","해결 방법: 종이의 뒷면을 써요.","자신의 생각: 아직 더 쓸 수 있으니까 종이의 뒷면도 쓰면 좋겠어요."],"title":"『국어』 185쪽 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#3','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C3',1,'mc','auto','『국어』 187쪽 — 「쓰레기를 스스로 주울 때」는 언제 빛나는 때인가요?',ARRAY['K1-2-u6-X08','K1-2-u6-X09']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 187쪽 — 「쓰레기를 스스로 주울 때」는 언제 빛나는 때인가요?","options":[{"t":"나 혼자 반짝 빛날 때","correct":true},{"t":"여럿이 함께 빛날 때","mis":"K1-2-u6-X08"},{"t":"빛나지 않는 때","mis":"K1-2-u6-X09"}],"explanation":["스스로 하는 일로 혼자 빛나요.","187쪽 (1)이에요.","말풍선을 읽어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"쓰레기를 스스로 주울 때 나 혼자 반짝 빛날 수 있어."},{"who":"친구 2","text":"내 생각을 마음껏 표현할 때에도 그래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#4','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C4',1,'mc','auto','『국어』 210쪽 1번 — 까만 덩어리 땔감을 바르게 쓴 것은?',ARRAY['K1-2-u6-X11','K1-2-u6-X10']::text[],false,'{"seq":4,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"『국어』 210쪽 1번 — 까만 덩어리 땔감을 바르게 쓴 것은?","options":[{"t":"숯","correct":true},{"t":"숫","mis":"K1-2-u6-X11"},{"t":"숟","mis":"K1-2-u6-X10"}],"explanation":["[숟]으로 소리 나도 「숯」으로 써요.","「숫」은 다른 뜻이에요.","210쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#5','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은?","options":[{"t":"소화전 근처에는 ∨ 주차하면 안 됩니다.","correct":true},{"t":"소화전근처에는주차하면안됩니다.","mis":"K1-2-u6-X14"},{"t":"소 ∨ 화 ∨ 전 ∨ 근 ∨ 처 ∨ 에 ∨ 는 ∨ 주차하면 안 됩니다.","mis":"K1-2-u6-X13"}],"explanation":["알맞게 띄어 읽었어요.","붙이거나 글자마다 끊으면 어색해요.","지도서 255쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#6','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C6',1,'mc','auto','「괜찮아 아저씨」에서 아저씨가 아침마다 한 일은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"「괜찮아 아저씨」에서 아저씨가 아침마다 한 일은?","options":[{"t":"세수를 하고 머리 모양을 만들었어요","correct":true},{"t":"머리카락을 모두 잘랐어요","mis":"K1-2-u6-X17"},{"t":"모자를 샀어요","mis":"K1-2-u6-X17"}],"explanation":["아침마다 머리 모양을 만들었어요.","글에 없는 일은 고르지 않아요.","196쪽이에요."],"asset":{"type":"passage","lines":["아저씨는 아침마다 세수를 하고 머리 모양을 만들어요.","머리카락은 처음에 열 올이었어요.","새·거미·곰·토끼를 만날 때마다 한 올씩 쏘옥 빠져요.","아저씨는 남은 머리카락을 묶고, 가르마를 타고, 말고, 땋았어요.","그리고 늘 이렇게 말해요. “오, 괜찮은데?”"],"title":"「괜찮아 아저씨」(김경희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#7','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C7',1,'mc','auto','『국어』 208쪽 — 공작새가 부러워한 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"『국어』 208쪽 — 공작새가 부러워한 것은?","options":[{"t":"꾀꼬리의 아름다운 목소리","correct":true},{"t":"꾀꼬리의 깃털","mis":"K1-2-u6-X17"},{"t":"하늘의 구름","mis":"K1-2-u6-X17"}],"explanation":["꾀꼬리의 목소리를 부러워했어요.","첫 줄이에요.","대본을 읽어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
