INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#9','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C4',2,'match','auto','『국어』 189쪽 — 뜻과 낱말을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C4","difficulty":2,"kind":"match","stem":"『국어』 189쪽 — 뜻과 낱말을 이어 보세요.","pairs":[{"l":"해가 떠 있는 때","r":"낮"},{"l":"풀을 베는 도구","r":"낫"},{"l":"얼굴","r":"낯"}],"mis":"K1-2-u6-X11","explanation":["모두 [낟]으로 소리 나요.","뜻에 맞는 받침을 써요.","189쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#10','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C6',2,'match','auto','「괜찮아 아저씨」 — 만난 것과 모습을 나타내는 말을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「괜찮아 아저씨」 — 만난 것과 모습을 나타내는 말을 이어 보세요.","pairs":[{"l":"새들","r":"포르르"},{"l":"거미","r":"흔들흔들"},{"l":"곰과 시소","r":"오르락내리락"}],"mis":"K1-2-u6-X17","explanation":["흉내 내는 말이 장면을 그려요.","장면마다 한 올씩 빠졌어요.","지도서 262쪽이에요."],"asset":{"type":"passage","lines":["낮잠을 자는데 새들이 포르르 — 한 올이 쏘옥","비 오는 날 거미가 흔들흔들 — 한 올이 쏘옥","곰이랑 시소를 오르락내리락 — 한 올이 쏘옥","토끼랑 깡충깡충 달리기 — 한 올이 쏘옥"],"title":"『국어』 198~204쪽 — 머리카락이 빠진 까닭(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#11','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C1',2,'mc','auto','『국어활동』 62쪽 — 생각이 잘 드러나게 문장으로 표현한 것은?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":11,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"『국어활동』 62쪽 — 생각이 잘 드러나게 문장으로 표현한 것은?","options":[{"t":"안전을 위해 차에서는 안전띠를 풀지 않아야 해요.","correct":true},{"t":"하면 안 돼요.","mis":"K1-2-u6-X01"},{"t":"차가 좋아요.","mis":"K1-2-u6-X01"}],"explanation":["무엇을 왜 해야 하는지 드러나요.","한마디로는 생각이 드러나지 않아요.","국어활동 62쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#12','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C2',2,'mc','auto','「더 쓸 수 있는 종이를 버리려고 해요.」에 알맞은 해결 방법은?',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":12,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"「더 쓸 수 있는 종이를 버리려고 해요.」에 알맞은 해결 방법은?","options":[{"t":"종이의 빈 부분을 더 써요","correct":true},{"t":"종이를 아예 쓰지 않아요","mis":"K1-2-u6-X05"},{"t":"종이를 더 많이 꺼내요","mis":"K1-2-u6-X05"}],"explanation":["빈 부분을 쓰면 아낄 수 있어요.","쓰지 않거나 더 꺼내면 문제가 그대로예요.","184쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#13','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C3',2,'mc','auto','『국어』 187쪽 (3) — 어떻게 빛나고 싶은지 문장으로 쓴 것은?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":13,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"『국어』 187쪽 (3) — 어떻게 빛나고 싶은지 문장으로 쓴 것은?","options":[{"t":"부끄럽지만 용기를 내어 손을 들고 내 생각을 발표하는 별이 되고 싶어요.","correct":true},{"t":"별.","mis":"K1-2-u6-X01"},{"t":"반짝반짝.","mis":"K1-2-u6-X01"}],"explanation":["문장으로 분명하게 썼어요.","낱말 하나로는 생각이 드러나지 않아요.","187쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#14','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C7',2,'mc','auto','지도서 265쪽 — 친구의 목소리 연극을 평가할 때 살펴볼 것은?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":14,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"지도서 265쪽 — 친구의 목소리 연극을 평가할 때 살펴볼 것은?","options":[{"t":"문장을 자연스럽게 읽고 있는지","correct":true},{"t":"친구의 외모가 어떤지","mis":"K1-2-u6-X19"},{"t":"누가 가장 빨리 끝냈는지","mis":"K1-2-u6-X19"}],"explanation":["자연스럽게 읽는지에 초점을 둬요.","외모나 빠르기는 평가하지 않아요.","지도서 265쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#15','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C5',2,'ox','auto','『국어』 192쪽 — 띄어 읽는 곳은 문장마다 딱 한 군데로 정해져 있어요.',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":15,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"『국어』 192쪽 — 띄어 읽는 곳은 문장마다 딱 한 군데로 정해져 있어요.","answer":"X","reason_options":[{"t":"뜻이 통하면 쉬는 곳은 여럿일 수 있으니까","correct":true},{"t":"정답은 언제나 하나뿐이니까","mis":"K1-2-u6-X15"}],"mis":"K1-2-u6-X15","explanation":["두 가지 띄어 읽기 모두 뜻이 통했어요.","뜻이 잘 드러나는지가 기준이에요.","지도서 256쪽이에요."],"asset":{"type":"passage","lines":["첫 번째: 불이 나면 ∨ 모두의 안전을 위해 ∨ 건물에서 ∨ 멀리 떨어진 곳으로 ∨ 대피해야 합니다.","두 번째: 불이 나면 ∨ 모두의 안전을 위해 ∨ 건물에서 멀리 떨어진 곳으로 ∨ 대피해야 합니다."],"title":"『국어』 192쪽 — 두 가지 띄어 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
