INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#19','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C2',3,'ox','auto','「자신의 생각」에는 까닭을 넣지 않아도 돼요.',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":19,"concept":"K1-2-u6-C2","difficulty":3,"kind":"ox","stem":"「자신의 생각」에는 까닭을 넣지 않아도 돼요.","answer":"X","reason_options":[{"t":"왜 그렇게 생각했는지가 있어야 생각이 잘 전해지니까","correct":true},{"t":"까닭은 「문제」 칸에만 쓰는 것이니까","mis":"K1-2-u6-X06"}],"mis":"K1-2-u6-X02","explanation":["자신의 생각에는 까닭을 넣어요.","「~니까 ~면 좋겠어요」.","185쪽 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#20','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C6',3,'mc','auto','지도서 258쪽 — 「아저씨는 머리카락 숫자를 세었어요.」에서 조금 쉬어 읽으면 좋은 곳은?',ARRAY['K1-2-u6-X13','K1-2-u6-X16']::text[],false,'{"seq":20,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"지도서 258쪽 — 「아저씨는 머리카락 숫자를 세었어요.」에서 조금 쉬어 읽으면 좋은 곳은?","options":[{"t":"「아저씨는」 뒤","correct":true},{"t":"「머리」 뒤","mis":"K1-2-u6-X13"},{"t":"어디에서도 쉬지 않아요","mis":"K1-2-u6-X16"}],"explanation":["「누가」 뒤에서 조금 쉬어요.","낱말 가운데에서는 쉬지 않아요.","지도서 258쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
