INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#22','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C3',3,'mc','auto','시 「반짝반짝」을 읽고 알맞게 생각한 것은?',ARRAY['K1-2-u6-X09']::text[],false,'{"seq":22,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"시 「반짝반짝」을 읽고 알맞게 생각한 것은?","options":[{"t":"혼자 하는 일도, 함께 하는 일도 모두 소중해요","correct":true},{"t":"혼자 하는 일은 소용없어요","mis":"K1-2-u6-X09"},{"t":"함께 하는 일은 필요 없어요","mis":"K1-2-u6-X09"}],"explanation":["혼자서도 빛나고, 모이면 더 빛나요.","둘 다 소중해요.","지도서 250쪽이에요."],"asset":{"type":"passage","lines":["시 「반짝반짝」은 우리에게 두 가지를 물어요.","하나는 혼자서 빛나는 별이 되고 싶은지,","하나는 여럿이 모여 빛나는 별자리가 되고 싶은지예요."],"title":"『국어』 186쪽 — 시가 묻는 것(풀어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#23','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C8',4,'sa','auto','『국어』 212쪽 — 「싫다」의 반대말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u6-C8","difficulty":4,"kind":"sa","stem":"『국어』 212쪽 — 「싫다」의 반대말을 쓰세요.","answer":["좋다","좋아요"],"explanation":["싫다의 반대말은 좋다예요.","212쪽 1번이에요.","반대 짝."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#24','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C1',4,'essay','teacher','지도서 271쪽 평가 — 공원 그림을 보고 보기처럼 친구들에게 해 주고 싶은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#25','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C3',4,'essay','teacher','시 「반짝반짝」을 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"시 「반짝반짝」을 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.","answer_guide":{"answer":"예: 혼자서도 빛날 수 있어요. 모이면 더 크게 빛나요. 나는 쉬는 시간에 혼자 있는 친구에게 같이 놀자고 하겠어요. — 시에서 온 생각과 할 일이 짧은 문장으로 있으면 맞아요.","scoring_points":["시에서 온 생각이 내 말로 있는가","우리 반을 위한 할 일이 있는가","짧은 문장 여러 개로 나누었는가"]},"explanation":["짧은 문장 여러 개로 써요.","혼자도 함께도 소중해요.","지도서 250쪽이에요."],"asset":{"type":"passage","lines":["시 「반짝반짝」은 우리에게 두 가지를 물어요.","하나는 혼자서 빛나는 별이 되고 싶은지,","하나는 여럿이 모여 빛나는 별자리가 되고 싶은지예요."],"title":"『국어』 186쪽 — 시가 묻는 것(풀어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#1','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C1',1,'mc','auto','『국어』 180쪽 — 그림 속 친구에게 해 주고 싶은 말로 알맞은 것은?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"『국어』 180쪽 — 그림 속 친구에게 해 주고 싶은 말로 알맞은 것은?","options":[{"t":"앞사람이 불편할 수도 있으니까 앞자리를 발로 차면 안 돼.","correct":true},{"t":"싫어.","mis":"K1-2-u6-X01"},{"t":"나가.","mis":"K1-2-u6-X02"}],"explanation":["까닭과 할 일이 함께 있어요.","한마디로는 생각이 전해지지 않아요.","180쪽이에요."],"asset":{"type":"scene","icon":"🦶💺","text":"영화관에서 한 친구가 앞자리를 발로 차요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#2','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C2',1,'mc','auto','지우개를 보고 쓴 생각에서 「해결 방법」 칸에 쓴 것은?',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"지우개를 보고 쓴 생각에서 「해결 방법」 칸에 쓴 것은?","options":[{"t":"지우개는 글씨를 지울 때만 써요.","correct":true},{"t":"지우개를 잘라서 놀이를 해요.","mis":"K1-2-u6-X06"},{"t":"지우개가 금방 없어지니까 아껴 쓰면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["둘째 칸이에요.","첫째는 문제, 셋째는 자신의 생각이에요.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 지우개를 잘라서 놀이를 해요.","해결 방법: 지우개는 글씨를 지울 때만 써요.","자신의 생각: 지우개가 금방 없어지니까 아껴 쓰면 좋겠어요."],"title":"지우개를 보고 쓴 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#3','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C3',1,'mc','auto','『국어』 187쪽 — 「내 생각을 마음껏 표현할 때」는 언제 빛나는 때인가요?',ARRAY['K1-2-u6-X08','K1-2-u6-X09']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 187쪽 — 「내 생각을 마음껏 표현할 때」는 언제 빛나는 때인가요?","options":[{"t":"나 혼자 반짝 빛날 때","correct":true},{"t":"여럿이 함께 빛날 때","mis":"K1-2-u6-X08"},{"t":"빛나지 않는 때","mis":"K1-2-u6-X09"}],"explanation":["나 혼자 반짝 빛날 수 있어요.","187쪽 (1)이에요.","말풍선을 읽어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"쓰레기를 스스로 주울 때 나 혼자 반짝 빛날 수 있어."},{"who":"친구 2","text":"내 생각을 마음껏 표현할 때에도 그래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#4','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C4',1,'mc','auto','『국어』 210쪽 1번 — 나무의 잎을 바르게 쓴 것은?',ARRAY['K1-2-u6-X11','K1-2-u6-X10']::text[],false,'{"seq":4,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"『국어』 210쪽 1번 — 나무의 잎을 바르게 쓴 것은?","options":[{"t":"잎","correct":true},{"t":"입","mis":"K1-2-u6-X11"},{"t":"잋","mis":"K1-2-u6-X10"}],"explanation":["나무의 잎은 「잎」이에요.","「입」은 몸의 한 부분이에요.","210쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#5','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은?","options":[{"t":"소방관은 ∨ 불이 났을 때 ∨ 소화전에 ∨ 호스를 연결해서 ∨ 물을 얻는답니다.","correct":true},{"t":"소방관은불이났을때소화전에호스를연결해서물을얻는답니다.","mis":"K1-2-u6-X14"},{"t":"소방 ∨ 관은 불이 났 ∨ 을 때 소화 ∨ 전에 호스를","mis":"K1-2-u6-X13"}],"explanation":["알맞게 띄어 읽었어요.","붙이거나 낱말을 자르면 어색해요.","지도서 255쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#6','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C6',1,'mc','auto','「괜찮아 아저씨」에서 머리카락은 처음에 몇 올이었나요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"「괜찮아 아저씨」에서 머리카락은 처음에 몇 올이었나요?","options":[{"t":"열 올","correct":true},{"t":"다섯 올","mis":"K1-2-u6-X17"},{"t":"스무 올","mis":"K1-2-u6-X17"}],"explanation":["처음에는 열 올이었어요.","197쪽 그림에서 세어요.","197쪽이에요."],"asset":{"type":"passage","lines":["아저씨는 아침마다 세수를 하고 머리 모양을 만들어요.","머리카락은 처음에 열 올이었어요.","새·거미·곰·토끼를 만날 때마다 한 올씩 쏘옥 빠져요.","아저씨는 남은 머리카락을 묶고, 가르마를 타고, 말고, 땋았어요.","그리고 늘 이렇게 말해요. “오, 괜찮은데?”"],"title":"「괜찮아 아저씨」(김경희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#7','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C7',1,'mc','auto','『국어』 208쪽 — 꾀꼬리가 알려 준 공작새의 좋은 점은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"『국어』 208쪽 — 꾀꼬리가 알려 준 공작새의 좋은 점은?","options":[{"t":"아름다운 깃털","correct":true},{"t":"예쁜 목소리","mis":"K1-2-u6-X17"},{"t":"빠른 다리","mis":"K1-2-u6-X17"}],"explanation":["아름다운 깃털이 있잖아.","꾀꼬리의 말이에요.","둘째 줄이에요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
