INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#10','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C6',2,'match','auto','「괜찮아 아저씨」 — 머리카락 수와 머리 모양을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「괜찮아 아저씨」 — 머리카락 수와 머리 모양을 이어 보세요.","pairs":[{"l":"아홉 올","r":"세 개씩 묶었어요"},{"l":"여덟 올","r":"가르마를 탔어요"},{"l":"여섯 올","r":"땋았어요"}],"mis":"K1-2-u6-X17","explanation":["글과 그림을 함께 봐요.","한 올씩 줄어들어요.","199~205쪽이에요."],"asset":{"type":"passage","lines":["아홉 올 — 세 개씩 묶었어요.","여덟 올 — 가르마를 탔어요.","일곱 올 — 꼬불꼬불 말았어요.","여섯 올 — 땋았어요."],"title":"『국어』 199~205쪽 — 머리카락 수와 머리 모양"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
