INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#13','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C3',2,'mc','auto','『국어』 187쪽 (3) — 어떻게 빛나고 싶은지 문장으로 쓴 것은?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":13,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"『국어』 187쪽 (3) — 어떻게 빛나고 싶은지 문장으로 쓴 것은?","options":[{"t":"놀이 시간에 가지고 논 놀잇감을 친구들과 함께 정리하는 별자리가 되고 싶어요.","correct":true},{"t":"별자리.","mis":"K1-2-u6-X01"},{"t":"정리.","mis":"K1-2-u6-X01"}],"explanation":["문장으로 분명하게 썼어요.","낱말 하나로는 생각이 드러나지 않아요.","187쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
