INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#22','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C3',3,'mc','auto','지도서 250쪽 — 누가 보지 않아도 스스로 하는 일은 어떤 가치가 있나요?',ARRAY['K1-2-u6-X09']::text[],false,'{"seq":22,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"지도서 250쪽 — 누가 보지 않아도 스스로 하는 일은 어떤 가치가 있나요?","options":[{"t":"나 혼자서도 반짝 빛날 수 있게 해요","correct":true},{"t":"아무 쓸모가 없어요","mis":"K1-2-u6-X09"},{"t":"여럿이 있을 때만 빛나요","mis":"K1-2-u6-X09"}],"explanation":["스스로 하는 일도 빛나요.","이런 사람이 모이면 더 빛나요.","지도서 250쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#23','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C8',4,'sa','auto','『국어』 212쪽 — 「더럽다」의 반대말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u6-C8","difficulty":4,"kind":"sa","stem":"『국어』 212쪽 — 「더럽다」의 반대말을 쓰세요.","answer":["깨끗하다","깨끗해요"],"explanation":["더럽다의 반대말은 깨끗하다예요.","212쪽 1번이에요.","반대 짝."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#24','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C1',4,'essay','teacher','지도서 267쪽 — 길을 건널 때 지켜야 할 점을 떠올리며, 늑대에게 해 주고 싶은 말을 「늑대야,」로 시작해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"지도서 267쪽 — 길을 건널 때 지켜야 할 점을 떠올리며, 늑대에게 해 주고 싶은 말을 「늑대야,」로 시작해 쓰세요.","answer_guide":{"answer":"예: 늑대야, 길을 건너기 전에는 차가 멈추었는지 꼭 확인해야 해. — 지켜야 할 점과 까닭이 있으면 맞아요.","scoring_points":["늑대에게 하는 말인가","지켜야 할 점이 있는가","완결된 문장인가"]},"explanation":["규칙 두 가지를 떠올려요.","까닭을 넣으면 더 좋아요.","지도서 267쪽이에요."],"asset":{"type":"passage","lines":["규칙 1. 길을 건너기 전에는 차가 멈추었는지 확인해요.","규칙 2. 횡단보도를 건널 때에는 좌우를 살펴요."],"title":"지도서 267쪽 — 길을 건널 때 지켜야 할 점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#25','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C5',4,'essay','teacher','(∨ 는 쉬어 읽는 곳이에요.) 지도서 273쪽 평가 — 「개미들이 줄지어 가는 것을 보았다.」와 「개미를 따라가 보니 하나의 구멍으로 들어갔다.」를 뜻이 잘 드러나게 ∨ 를 넣어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u6-C5","difficulty":4,"kind":"essay","stem":"(∨ 는 쉬어 읽는 곳이에요.) 지도서 273쪽 평가 — 「개미들이 줄지어 가는 것을 보았다.」와 「개미를 따라가 보니 하나의 구멍으로 들어갔다.」를 뜻이 잘 드러나게 ∨ 를 넣어 쓰세요.","answer_guide":{"answer":"예: 개미들이 ∨ 줄지어 가는 것을 보았다. / 개미를 따라가 보니 ∨ 하나의 구멍으로 들어갔다. — 낱말 가운데를 자르지 않고 뜻이 통하면 맞아요.","scoring_points":["낱말 가운데에서 쉬지 않았는가","뜻이 통하는 덩어리로 나누었는가","두 문장 모두 썼는가"]},"explanation":["「누가」 뒤에서 조금 쉬어요.","정답은 하나가 아니에요.","지도서 272~273쪽이에요."],"asset":{"type":"passage","lines":["개미들이 줄지어 가는 것을 보았다.","어디로 가는 것일까?","개미를 따라가 보니 하나의 구멍으로 들어갔다.","새집으로 이사를 가나?","개미들이 줄지어 움직이는 모습이 참 신기했다."],"title":"지도서 273쪽 평가 — 개미"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#1','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C1',1,'mc','auto','『국어』 181쪽 — 그림 속 친구에게 해 주고 싶은 말로 알맞은 것은?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"『국어』 181쪽 — 그림 속 친구에게 해 주고 싶은 말로 알맞은 것은?","options":[{"t":"영화관에서는 휴대 전화에서 소리나 진동이 울리지 않게 해야 해.","correct":true},{"t":"시끄러워.","mis":"K1-2-u6-X01"},{"t":"꺼.","mis":"K1-2-u6-X02"}],"explanation":["무엇을 어떻게 해야 하는지 말했어요.","한마디로는 생각이 전해지지 않아요.","181쪽이에요."],"asset":{"type":"scene","icon":"📳🎬","text":"영화를 보는데 한 친구의 휴대 전화가 울려요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#2','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C2',1,'mc','auto','테이프를 보고 쓴 생각에서 「해결 방법」 칸에 쓴 것은?',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"테이프를 보고 쓴 생각에서 「해결 방법」 칸에 쓴 것은?","options":[{"t":"필요한 만큼만 잘라 붙여요.","correct":true},{"t":"테이프를 너무 길게 많이 써요.","mis":"K1-2-u6-X06"},{"t":"버려지는 테이프가 줄어드니까 조금씩 쓰면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["둘째 칸이에요.","첫째는 문제, 셋째는 자신의 생각이에요.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 테이프를 너무 길게 많이 써요.","해결 방법: 필요한 만큼만 잘라 붙여요.","자신의 생각: 버려지는 테이프가 줄어드니까 조금씩 쓰면 좋겠어요."],"title":"테이프를 보고 쓴 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#3','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C3',1,'mc','auto','『국어』 187쪽 — 「함께 즐거움을 느낄 때」는 언제 빛나는 때인가요?',ARRAY['K1-2-u6-X08','K1-2-u6-X09']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 187쪽 — 「함께 즐거움을 느낄 때」는 언제 빛나는 때인가요?","options":[{"t":"여럿이 함께 빛날 때","correct":true},{"t":"나 혼자 빛날 때","mis":"K1-2-u6-X08"},{"t":"빛나지 않는 때","mis":"K1-2-u6-X09"}],"explanation":["우리 모두 빛날 수 있어요.","187쪽 (2)예요.","말풍선을 읽어요."],"asset":{"type":"speech","turns":[{"who":"친구 3","text":"함께 즐거움을 느낄 때 우리 모두 빛날 수 있어."},{"who":"친구 4","text":"도움이 필요한 친구를 함께 도와줄 때에도 그래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#4','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C4',1,'mc','auto','『국어』 210쪽 1번 — 창문 바깥을 뜻하는 낱말을 바르게 쓴 것은?',ARRAY['K1-2-u6-X11','K1-2-u6-X10']::text[],false,'{"seq":4,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"『국어』 210쪽 1번 — 창문 바깥을 뜻하는 낱말을 바르게 쓴 것은?","options":[{"t":"밖","correct":true},{"t":"박","mis":"K1-2-u6-X11"},{"t":"밗","mis":"K1-2-u6-X10"}],"explanation":["바깥은 「밖」이에요.","「박」은 다른 뜻이에요.","210쪽 1번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#5','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은?","options":[{"t":"개는 ∨ 혀로 ∨ 더위를 식힙니다.","correct":true},{"t":"개는혀로더위를식힙니다.","mis":"K1-2-u6-X14"},{"t":"개 ∨ 는 ∨ 혀 ∨ 로 ∨ 더 ∨ 위 ∨ 를","mis":"K1-2-u6-X13"}],"explanation":["알맞게 띄어 읽었어요.","붙이거나 글자마다 끊으면 어색해요.","국어활동 65쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#6','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C6',1,'mc','auto','「괜찮아 아저씨」에서 아저씨가 늘 한 말은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"「괜찮아 아저씨」에서 아저씨가 늘 한 말은?","options":[{"t":"“오, 괜찮은데?”","correct":true},{"t":"“아, 속상해.”","mis":"K1-2-u6-X17"},{"t":"“다시는 안 할래.”","mis":"K1-2-u6-X17"}],"explanation":["늘 「오, 괜찮은데?」라고 했어요.","밝은 마음이 담겨 있어요.","되풀이되는 말이에요."],"asset":{"type":"passage","lines":["아저씨는 아침마다 세수를 하고 머리 모양을 만들어요.","머리카락은 처음에 열 올이었어요.","새·거미·곰·토끼를 만날 때마다 한 올씩 쏘옥 빠져요.","아저씨는 남은 머리카락을 묶고, 가르마를 타고, 말고, 땋았어요.","그리고 늘 이렇게 말해요. “오, 괜찮은데?”"],"title":"「괜찮아 아저씨」(김경희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#7','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C7',1,'mc','auto','『국어』 208쪽 — 목소리 연극에 나오지 않는 인물은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"『국어』 208쪽 — 목소리 연극에 나오지 않는 인물은?","options":[{"t":"호랑이","correct":true},{"t":"꾀꼬리","mis":"K1-2-u6-X17"},{"t":"하늘","mis":"K1-2-u6-X17"}],"explanation":["공작새, 꾀꼬리, 하늘이 나와요.","호랑이는 다른 대본이에요.","208쪽이에요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
