INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#9','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C4',2,'match','auto','『국어』 210쪽 — 자음자와 이름을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C4","difficulty":2,"kind":"match","stem":"『국어』 210쪽 — 자음자와 이름을 이어 보세요.","pairs":[{"l":"ㅊ","r":"치읓"},{"l":"ㅋ","r":"키읔"},{"l":"ㅍ","r":"피읖"}],"mis":"K1-2-u6-X12","explanation":["이름 끝 받침에 그 자음자가 있어요.","소리대로 쓰지 않아요.","210쪽 2번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#10','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C6',2,'match','auto','「괜찮아 아저씨」 — 일어난 일과 머리카락이 빠진 까닭을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「괜찮아 아저씨」 — 일어난 일과 머리카락이 빠진 까닭을 이어 보세요.","pairs":[{"l":"낮잠을 잘 때","r":"새들이 포르르 날아와서"},{"l":"비 오는 날","r":"거미가 매달려서"},{"l":"달리기 경주","r":"토끼와 깡충깡충 달려서"}],"mis":"K1-2-u6-X17","explanation":["장면마다 까닭이 달라요.","206쪽 (1)이에요.","그림을 함께 봐요."],"asset":{"type":"passage","lines":["낮잠을 자는데 새들이 포르르 — 한 올이 쏘옥","비 오는 날 거미가 흔들흔들 — 한 올이 쏘옥","곰이랑 시소를 오르락내리락 — 한 올이 쏘옥","토끼랑 깡충깡충 달리기 — 한 올이 쏘옥"],"title":"『국어』 198~204쪽 — 머리카락이 빠진 까닭(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#11','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C1',2,'mc','auto','『국어활동』 62쪽 — 생각이 잘 드러나게 문장으로 표현한 것은?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":11,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"『국어활동』 62쪽 — 생각이 잘 드러나게 문장으로 표현한 것은?","options":[{"t":"이 책은 주인공이 모험을 하는 내용이 있어서 재미있어요.","correct":true},{"t":"이 책은 좋아요.","mis":"K1-2-u6-X01"},{"t":"책이에요.","mis":"K1-2-u6-X01"}],"explanation":["왜 재미있는지 까닭이 있어요.","「좋아요」만으로는 아쉬워요.","국어활동 62쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#12','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C2',2,'mc','auto','「테이프를 너무 길게 많이 써요.」에 알맞은 해결 방법은?',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":12,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"「테이프를 너무 길게 많이 써요.」에 알맞은 해결 방법은?","options":[{"t":"필요한 만큼만 잘라 붙여요","correct":true},{"t":"테이프를 한 통 더 써요","mis":"K1-2-u6-X05"},{"t":"종이접기를 그만둬요","mis":"K1-2-u6-X05"}],"explanation":["필요한 만큼만 쓰면 돼요.","더 쓰거나 그만두는 것은 방법이 아니에요.","지도서 248쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#13','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C3',2,'mc','auto','『국어』 188쪽 — 우리 반을 위해 할 수 있는 일을 문장으로 쓴 것은?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":13,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"『국어』 188쪽 — 우리 반을 위해 할 수 있는 일을 문장으로 쓴 것은?","options":[{"t":"나는 아침마다 교실 화분에 물을 주겠어요.","correct":true},{"t":"화분.","mis":"K1-2-u6-X01"},{"t":"우리 반이 좋아요.","mis":"K1-2-u6-X01"}],"explanation":["무엇을 할지 문장으로 썼어요.","낱말이나 느낌만으로는 할 일이 드러나지 않아요.","188쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#14','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C7',2,'mc','auto','지도서 265쪽 — 친구의 읽기를 평가할 때 살펴보지 않는 것은?',ARRAY['K1-2-u6-X13','K1-2-u6-X18']::text[],false,'{"seq":14,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"지도서 265쪽 — 친구의 읽기를 평가할 때 살펴보지 않는 것은?","options":[{"t":"친구의 말하기 습관이나 외모","correct":true},{"t":"자연스럽게 띄어 읽었는지","mis":"K1-2-u6-X13"},{"t":"문장 부호를 살렸는지","mis":"K1-2-u6-X18"}],"explanation":["외모나 말버릇은 평가하지 않아요.","읽기에 대한 것만 살펴요.","지도서 265쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#15','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C5',2,'ox','auto','친구와 쉬는 곳이 달라도 뜻이 잘 통하면 괜찮아요.',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":15,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"친구와 쉬는 곳이 달라도 뜻이 잘 통하면 괜찮아요.","answer":"O","reason_options":[{"t":"뜻이 이어지는 덩어리는 여러 가지로 묶을 수 있으니까","correct":true},{"t":"나와 같은 곳에서 쉬어야 맞으니까","mis":"K1-2-u6-X15"}],"mis":"K1-2-u6-X15","explanation":["둘 다 맞을 수 있어요.","친구의 띄어 읽기도 존중해요.","지도서 245쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
