INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#19','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C2',3,'ox','auto','생각을 쓸 때 문제를 먼저 쓰고 해결 방법, 자신의 생각 차례로 써요.',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":19,"concept":"K1-2-u6-C2","difficulty":3,"kind":"ox","stem":"생각을 쓸 때 문제를 먼저 쓰고 해결 방법, 자신의 생각 차례로 써요.","answer":"O","reason_options":[{"t":"무엇이 문제인지 알아야 방법과 생각이 이해되니까","correct":true},{"t":"차례는 아무렇게나 써도 같으니까","mis":"K1-2-u6-X06"}],"mis":"K1-2-u6-X06","explanation":["문제 → 해결 방법 → 자신의 생각.","185쪽 보기 차례예요.","문제부터."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#20','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C6',3,'mc','auto','「오, 괜찮은데?」에 담긴 아저씨의 마음으로 알맞은 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":20,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"「오, 괜찮은데?」에 담긴 아저씨의 마음으로 알맞은 것은?","options":[{"t":"문제가 생겨도 밝고 재치 있게 받아들이는 마음","correct":true},{"t":"머리카락이 빠져서 화가 난 마음","mis":"K1-2-u6-X17"},{"t":"친구를 탓하는 마음","mis":"K1-2-u6-X17"}],"explanation":["바뀐 모습을 즐겁게 받아들였어요.","지도서 259쪽이에요.","아저씨의 표정을 떠올려요."],"asset":{"type":"passage","lines":["아저씨는 아침마다 세수를 하고 머리 모양을 만들어요.","머리카락은 처음에 열 올이었어요.","새·거미·곰·토끼를 만날 때마다 한 올씩 쏘옥 빠져요.","아저씨는 남은 머리카락을 묶고, 가르마를 타고, 말고, 땋았어요.","그리고 늘 이렇게 말해요. “오, 괜찮은데?”"],"title":"「괜찮아 아저씨」(김경희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#21','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C7',3,'error','auto','문장 부호에 따라 읽는 법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#22','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C3',3,'mc','auto','시에서 「별자리」가 뜻하는 것으로 알맞은 것은?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":22,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"시에서 「별자리」가 뜻하는 것으로 알맞은 것은?","options":[{"t":"여럿이 모여 함께 빛나는 모습","correct":true},{"t":"혼자 빛나는 모습","mis":"K1-2-u6-X08"},{"t":"빛이 꺼지는 모습","mis":"K1-2-u6-X08"}],"explanation":["별이 모이면 별자리예요.","여럿이 함께 빛나요.","188쪽이에요."],"asset":{"type":"passage","lines":["시 「반짝반짝」은 우리에게 두 가지를 물어요.","하나는 혼자서 빛나는 별이 되고 싶은지,","하나는 여럿이 모여 빛나는 별자리가 되고 싶은지예요."],"title":"『국어』 186쪽 — 시가 묻는 것(풀어 씀)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#23','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C8',4,'sa','auto','『국어』 212쪽 — 「들어가다」의 반대말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u6-C8","difficulty":4,"kind":"sa","stem":"『국어』 212쪽 — 「들어가다」의 반대말을 쓰세요.","answer":["나가다","나가요"],"explanation":["들어가다의 반대말은 나가다예요.","「안 들어가다」는 반대말이 아니에요.","지도서 269쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#24','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C1',4,'essay','teacher','『국어』 211쪽 — 링링에게 해 주고 싶은 말을 링링의 마음에 공감하며 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"『국어』 211쪽 — 링링에게 해 주고 싶은 말을 링링의 마음에 공감하며 문장으로 쓰세요.","answer_guide":{"answer":"예: 링링아, 열심히 준비했으니까 걱정하지 말고 자신 있게 발표해 봐! — 링링의 마음을 헤아린 응원과 까닭이 있으면 맞아요.","scoring_points":["링링의 마음에 공감했는가","응원하는 말이 있는가","완결된 문장인가"]},"explanation":["링링이 어떤 마음일지 먼저 생각해요.","공감을 바탕으로 말해요.","지도서 268쪽이에요."],"asset":{"type":"passage","lines":["발표 시간, 링링의 심장이 쿵쾅쿵쾅 뛰었어요.","온몸이 화끈거리고 머릿속이 하얘졌어요.","‘열심히 준비했는데 왜 입이 안 떨어지지?’","링링은 눈앞이 캄캄했어요."],"title":"『국어』 211쪽 — 링링 이야기(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#25','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C3',4,'essay','teacher','『국어』 187쪽 — 자신은 어떻게 빛나고 싶은지 「~하는 별(별자리)이 되고 싶어요.」로 쓰고, 그 까닭을 한 문장 더 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"『국어』 187쪽 — 자신은 어떻게 빛나고 싶은지 「~하는 별(별자리)이 되고 싶어요.」로 쓰고, 그 까닭을 한 문장 더 쓰세요.","answer_guide":{"answer":"예: 친구들과 교실을 함께 꾸미는 별자리가 되고 싶어요. 함께하면 더 멋진 교실이 되니까요. — 빛나고 싶은 모습과 까닭이 있으면 맞아요.","scoring_points":["어떻게 빛나고 싶은지 썼는가","까닭을 썼는가","짧은 문장으로 나누었는가"]},"explanation":["혼자인지 함께인지 생각해요.","까닭을 한 문장 더 써요.","187쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#1','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C1',1,'mc','auto','『국어』 181쪽 — 그림 속 친구에게 해 주고 싶은 말로 알맞은 것은?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"『국어』 181쪽 — 그림 속 친구에게 해 주고 싶은 말로 알맞은 것은?","options":[{"t":"쓰레기는 영화가 끝난 뒤에 밖에 있는 쓰레기통에 버려야 해.","correct":true},{"t":"더러워.","mis":"K1-2-u6-X01"},{"t":"치워.","mis":"K1-2-u6-X02"}],"explanation":["쓰레기를 어떻게 해야 하는지 말했어요.","한마디로는 생각이 전해지지 않아요.","181쪽이에요."],"asset":{"type":"scene","icon":"🍿🗑️","text":"영화관에서 한 친구가 다 먹은 팝콘 통을 바닥에 두고 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#2','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C2',1,'mc','auto','복도를 보고 쓴 생각에서 「해결 방법」 칸에 쓴 것은?',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"복도를 보고 쓴 생각에서 「해결 방법」 칸에 쓴 것은?","options":[{"t":"복도에서는 천천히 걸어요.","correct":true},{"t":"복도에서 뛰어다녀요.","mis":"K1-2-u6-X06"},{"t":"친구와 부딪혀 다칠 수 있으니까 걸어 다니면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["둘째 칸이에요.","첫째는 문제, 셋째는 자신의 생각이에요.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 복도에서 뛰어다녀요.","해결 방법: 복도에서는 천천히 걸어요.","자신의 생각: 친구와 부딪혀 다칠 수 있으니까 걸어 다니면 좋겠어요."],"title":"복도를 보고 쓴 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#3','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C3',1,'mc','auto','『국어』 187쪽 — 「도움이 필요한 친구를 함께 도와줄 때」는 언제 빛나는 때인가요?',ARRAY['K1-2-u6-X08','K1-2-u6-X09']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"『국어』 187쪽 — 「도움이 필요한 친구를 함께 도와줄 때」는 언제 빛나는 때인가요?","options":[{"t":"여럿이 함께 빛날 때","correct":true},{"t":"나 혼자 빛날 때","mis":"K1-2-u6-X08"},{"t":"빛나지 않는 때","mis":"K1-2-u6-X09"}],"explanation":["여럿이 함께 빛나요.","187쪽 (2)예요.","말풍선을 읽어요."],"asset":{"type":"speech","turns":[{"who":"친구 3","text":"함께 즐거움을 느낄 때 우리 모두 빛날 수 있어."},{"who":"친구 4","text":"도움이 필요한 친구를 함께 도와줄 때에도 그래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#4','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C4',1,'mc','auto','『국어』 190쪽 — 향기가 나는 「꽃」을 바르게 쓴 것은?',ARRAY['K1-2-u6-X10']::text[],false,'{"seq":4,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"『국어』 190쪽 — 향기가 나는 「꽃」을 바르게 쓴 것은?","options":[{"t":"꽃","correct":true},{"t":"꼳","mis":"K1-2-u6-X10"},{"t":"꼿","mis":"K1-2-u6-X10"}],"explanation":["[꼳]으로 소리 나도 「꽃」으로 써요.","받침 ㅊ이에요.","190쪽 4번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#5','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은?","options":[{"t":"개구리는 ∨ 혀로 ∨ 날아다니는 벌레를 ∨ 잡아먹습니다.","correct":true},{"t":"개구리는혀로날아다니는벌레를잡아먹습니다.","mis":"K1-2-u6-X14"},{"t":"개구리는 혀로 날아다 ∨ 니는 벌레를 잡아 ∨ 먹습니다.","mis":"K1-2-u6-X13"}],"explanation":["알맞게 띄어 읽었어요.","붙이거나 낱말을 자르면 어색해요.","국어활동 65쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#6','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C6',1,'mc','auto','지도서 259쪽 — 머리카락을 셀 때 쓰는 말로 알맞은 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"지도서 259쪽 — 머리카락을 셀 때 쓰는 말로 알맞은 것은?","options":[{"t":"올","correct":true},{"t":"마리","mis":"K1-2-u6-X17"},{"t":"그루","mis":"K1-2-u6-X17"}],"explanation":["머리카락은 올·가닥으로 세요.","마리는 동물, 그루는 나무예요.","지도서 259쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#7','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C7',1,'mc','auto','『국어』 208쪽 — 하늘이 공작새에게 주겠다고 한 것은?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"『국어』 208쪽 — 하늘이 공작새에게 주겠다고 한 것은?","options":[{"t":"깃털 대신 예쁜 목소리","correct":true},{"t":"더 큰 날개","mis":"K1-2-u6-X17"},{"t":"맛있는 먹이","mis":"K1-2-u6-X17"}],"explanation":["깃털 대신 목소리를 주겠다고 했어요.","하늘의 첫 대사예요.","대본을 읽어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"공작새는 꾀꼬리의 아름다운 목소리를 부러워했어요."},{"who":"꾀꼬리","text":"공작새야, 너에게는 아름다운 깃털이 있잖아."},{"who":"하늘","text":"공작새야, 너에게 아름다운 깃털 대신 예쁜 목소리를 주도록 하마!"},{"who":"공작새","text":"그건 안 돼요. 저는 지금 제 모습에서 목소리만 더 예뻐지고 싶은 거예요."},{"who":"하늘","text":"다른 사람을 부러워하고 욕심만 내기보다 자신의 좋은 점을 잘 살리려고 애쓰는 게 좋단다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
