INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#9','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C4',2,'match','auto','『국어』 210쪽 — 뜻과 바르게 쓴 낱말을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C4","difficulty":2,"kind":"match","stem":"『국어』 210쪽 — 뜻과 바르게 쓴 낱말을 이어 보세요.","pairs":[{"l":"까만 땔감","r":"숯"},{"l":"나무의 잎","r":"잎"},{"l":"창문 바깥","r":"밖"}],"mis":"K1-2-u6-X11","explanation":["소리가 비슷해도 뜻에 맞게 써요.","210쪽 1번이에요.","그림을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#10','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C6',2,'match','auto','「괜찮아 아저씨」 — 머리카락 수와 머리 모양을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「괜찮아 아저씨」 — 머리카락 수와 머리 모양을 이어 보세요.","pairs":[{"l":"일곱 올","r":"꼬불꼬불 말았어요"},{"l":"여덟 올","r":"가르마를 탔어요"},{"l":"아홉 올","r":"세 개씩 묶었어요"}],"mis":"K1-2-u6-X17","explanation":["글과 그림을 함께 봐요.","한 올씩 줄어들어요.","199~205쪽이에요."],"asset":{"type":"passage","lines":["아홉 올 — 세 개씩 묶었어요.","여덟 올 — 가르마를 탔어요.","일곱 올 — 꼬불꼬불 말았어요.","여섯 올 — 땋았어요."],"title":"『국어』 199~205쪽 — 머리카락 수와 머리 모양"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#11','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C1',2,'mc','auto','『국어활동』 63쪽 — 말하고 싶은 내용이 잘 드러나게 바꾼 것은?',ARRAY['K1-2-u6-X07','K1-2-u6-X01']::text[],false,'{"seq":11,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"『국어활동』 63쪽 — 말하고 싶은 내용이 잘 드러나게 바꾼 것은?","options":[{"t":"선생님, 현지가 사과를 받아 주지 않아서 어떻게 해야 할지 모르겠어요.","correct":true},{"t":"그런데요, 제가요, 아까요, 그런데요…","mis":"K1-2-u6-X07"},{"t":"몰라요.","mis":"K1-2-u6-X01"}],"explanation":["무엇이 문제인지 한 문장으로 분명하게 말했어요.","「그런데요」를 되풀이하면 뜻이 흐려져요.","국어활동 63쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#12','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C2',2,'mc','auto','「친구의 물건을 말없이 가져가 써요.」에 알맞은 해결 방법은?',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":12,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"「친구의 물건을 말없이 가져가 써요.」에 알맞은 해결 방법은?","options":[{"t":"쓰기 전에 친구에게 먼저 물어봐요","correct":true},{"t":"몰래 쓰고 돌려놓지 않아요","mis":"K1-2-u6-X05"},{"t":"친구 물건을 숨겨요","mis":"K1-2-u6-X05"}],"explanation":["먼저 물어보면 친구가 속상하지 않아요.","몰래 쓰거나 숨기면 안 돼요.","지도서 249쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#13','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C3',2,'mc','auto','『국어』 188쪽 — 우리 반을 위해 할 수 있는 일을 문장으로 쓴 것은?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":13,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"『국어』 188쪽 — 우리 반을 위해 할 수 있는 일을 문장으로 쓴 것은?","options":[{"t":"나는 급식을 먹고 내 자리를 깨끗이 닦겠어요.","correct":true},{"t":"급식.","mis":"K1-2-u6-X01"},{"t":"깨끗해요.","mis":"K1-2-u6-X01"}],"explanation":["무엇을 할지 문장으로 썼어요.","낱말이나 느낌만으로는 할 일이 드러나지 않아요.","188쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
