INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#19','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C2',3,'ox','auto','「문제」에는 그림에 없는 일을 지어내어 써도 돼요.',ARRAY['K1-2-u6-X04']::text[],false,'{"seq":19,"concept":"K1-2-u6-C2","difficulty":3,"kind":"ox","stem":"「문제」에는 그림에 없는 일을 지어내어 써도 돼요.","answer":"X","reason_options":[{"t":"그림에 보이는 문제를 써야 해결 방법이 맞으니까","correct":true},{"t":"문제는 크게 부풀려야 눈에 띄니까","mis":"K1-2-u6-X04"}],"mis":"K1-2-u6-X04","explanation":["보이는 문제를 써요.","지어낸 문제엔 방법도 맞지 않아요.","184쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
