INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#22','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C3',3,'mc','auto','우리 반 별자리를 만들 때 붙임딱지에 쓸 문장으로 알맞은 것은?',ARRAY['K1-2-u6-X01','K1-2-u6-X09']::text[],false,'{"seq":22,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"우리 반 별자리를 만들 때 붙임딱지에 쓸 문장으로 알맞은 것은?","options":[{"t":"나는 친구가 넘어지면 일으켜 주겠어요.","correct":true},{"t":"별자리.","mis":"K1-2-u6-X01"},{"t":"나만 잘하면 돼요.","mis":"K1-2-u6-X09"}],"explanation":["우리 반을 위한 할 일이에요.","이런 문장을 이어 붙여 별자리를 만들어요.","188쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#23','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C8',4,'sa','auto','『국어』 212쪽 — 「묶다」의 반대말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K1-2-u6-C8","difficulty":4,"kind":"sa","stem":"『국어』 212쪽 — 「묶다」의 반대말을 쓰세요.","answer":["풀다","풀어요"],"explanation":["묶다의 반대말은 풀다예요.","212쪽 1번이에요.","반대 짝."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#24','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C1',4,'essay','teacher','지도서 266쪽 — 동물의 왕은 어떤 동물인지 자신의 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"지도서 266쪽 — 동물의 왕은 어떤 동물인지 자신의 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 동물의 왕은 사자이다. 왜냐하면 힘이 가장 세고 달리기도 빠르기 때문이다. — 동물과 까닭이 완결된 문장으로 있으면 맞아요.","scoring_points":["어떤 동물인지 썼는가","까닭을 썼는가","완결된 문장인가"]},"explanation":["생각과 까닭을 함께 써요.","친구 생각과 달라도 괜찮아요.","지도서 266쪽이에요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"내가 왕이야. 나는 여기에서 가장 힘이 세고 빠르게 달릴 수 있어."},{"who":"원숭이","text":"힘만 세면 다니? 나는 긴 두 팔로 높은 나무에 매달릴 수 있단다."},{"who":"악어","text":"과연 그럴까? 나에게 한번 물리면 절대 벗어날 수 없어!"},{"who":"독수리","text":"아무리 빠르고 힘이 세도 하늘을 나는 나를 이길 수 있을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#25','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C5',4,'essay','teacher','(∨ 는 쉬어 읽는 곳이에요.) 「불이 나면 모두의 안전을 위해 건물에서 멀리 떨어진 곳으로 대피해야 합니다.」를 뜻이 잘 통하게 ∨ 를 넣어 쓰고, 왜 그곳에서 쉬었는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u6-C5","difficulty":4,"kind":"essay","stem":"(∨ 는 쉬어 읽는 곳이에요.) 「불이 나면 모두의 안전을 위해 건물에서 멀리 떨어진 곳으로 대피해야 합니다.」를 뜻이 잘 통하게 ∨ 를 넣어 쓰고, 왜 그곳에서 쉬었는지 쓰세요.","answer_guide":{"answer":"예: 불이 나면 ∨ 모두의 안전을 위해 ∨ 건물에서 멀리 떨어진 곳으로 ∨ 대피해야 합니다. — 뜻이 이어지는 말끼리 묶었어요. 낱말을 자르지 않고 까닭이 있으면 맞아요.","scoring_points":["낱말 가운데에서 쉬지 않았는가","뜻이 통하는 덩어리로 나누었는가","쉰 까닭을 썼는가"]},"explanation":["두 가지 방법 모두 뜻이 통했어요.","내 방법과 까닭을 써요.","192쪽이에요."],"asset":{"type":"passage","lines":["셋째, 불이 난 곳 근처에서 구경하지 말고 빠르게 대피해야 합니다.","건물에 불이 나면 불에 탄 물건이 머리 위로 떨어질 수도 있습니다.","불이 나면 모두의 안전을 위해 건물에서 멀리 떨어진 곳으로 대피해야 합니다."],"title":"「소방관의 부탁」 (3)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
